import AVFoundation
import AppKit
import CoreMedia
import CoreVideo
import Foundation
import Metal
import OSLog
import QuartzCore
import IlliquidCore

/// Minimal AppKit host used only by the PiP subtitle lifecycle host.
///
/// The view remains attached to a nonactivating, fully offscreen auxiliary
/// panel for the complete PiP session. Keeping the panel ordered in makes the
/// display layer render-active; an ordered-out layer accepts sample buffers
/// but never produces a displayed image for AVKit to mirror. The offscreen
/// panel survives main-window closure without becoming visible playback.
@MainActor
final class PiPSubtitleDisplayLayerHost {
    private final class HostView: NSView {
        let hostedDisplayLayer: AVSampleBufferDisplayLayer

        init(
            displayLayer: AVSampleBufferDisplayLayer,
            size: CGSize,
            scale: CGFloat
        ) {
            hostedDisplayLayer = displayLayer
            super.init(frame: CGRect(origin: .zero, size: size))
            wantsLayer = true
            layer = CALayer()
            layer?.backgroundColor = NSColor.clear.cgColor
            layer?.contentsScale = max(scale, 1)
            layer?.masksToBounds = false
            hostedDisplayLayer.removeFromSuperlayer()
            hostedDisplayLayer.contentsScale = 1
            hostedDisplayLayer.frame = bounds
            layer?.addSublayer(hostedDisplayLayer)
            setAccessibilityElement(false)
        }

        @available(*, unavailable)
        required init?(coder: NSCoder) {
            fatalError("init(coder:) has not been implemented")
        }

        override func layout() {
            super.layout()
            CATransaction.begin()
            CATransaction.setDisableActions(true)
            hostedDisplayLayer.frame = bounds
            CATransaction.commit()
        }

        deinit {
            PiPSubtitleDisplayLayerHost.emit("host-view-deinit")
        }
    }

    private let hostView: HostView
    private let panel: NSPanel
    private var isAttached = false

    init?(displayLayer: AVSampleBufferDisplayLayer, parentView: NSView) {
        guard parentView.window != nil else {
            Self.emit("host-attach-failed reason=parent-has-no-window")
            return nil
        }
        let initialSize = Self.validSize(displayLayer.bounds.size)
            ?? CGSize(width: 1, height: 1)
        hostView = HostView(
            displayLayer: displayLayer,
            size: initialSize,
            scale: parentView.window?.backingScaleFactor ?? 1
        )
        panel = NSPanel(
            contentRect: CGRect(
                origin: CGPoint(x: -10_000, y: -10_000),
                size: initialSize
            ),
            styleMask: [.borderless, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.hasShadow = false
        panel.animationBehavior = .none
        panel.ignoresMouseEvents = true
        panel.hidesOnDeactivate = false
        panel.isExcludedFromWindowsMenu = true
        // Swift/ARC clients must keep this false; AppKit otherwise
        // over-releases the window after `close()`.
        panel.isReleasedWhenClosed = false
        panel.collectionBehavior = [.auxiliary, .ignoresCycle]
        panel.contentView = hostView
        panel.orderFront(nil)
        panel.setFrameOrigin(CGPoint(x: -10_000, y: -10_000))
        isAttached = hostView.window === panel
            && displayLayer.superlayer === hostView.layer
        guard isAttached else {
            panel.contentView = nil
            panel.close()
            Self.emit("host-attach-failed reason=invalid-layer-hierarchy")
            return nil
        }
        Self.emit(
            "host-attached panel=true visible=\(panel.isVisible)"
                + " onscreen=\(panel.isOnActiveSpace && panel.occlusionState.contains(.visible))"
                + " bounds=\(Self.size(displayLayer.bounds.size))"
                + " scale=\(displayLayer.contentsScale)"
        )
    }

    func setSize(_ requestedSize: CGSize) {
        guard isAttached, let size = Self.validSize(requestedSize) else { return }
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        panel.setContentSize(size)
        hostView.frame = CGRect(origin: .zero, size: size)
        hostView.hostedDisplayLayer.frame = hostView.bounds
        CATransaction.commit()
    }

    func geometryForTesting() -> (
        panelSize: CGSize,
        viewSize: CGSize,
        layerFrame: CGRect,
        layerBounds: CGRect,
        panelFrame: CGRect,
        panelVisible: Bool
    ) {
        (
            panel.contentView?.bounds.size ?? .zero,
            hostView.bounds.size,
            hostView.hostedDisplayLayer.frame,
            hostView.hostedDisplayLayer.bounds,
            panel.frame,
            panel.isVisible
        )
    }

    func tearDown() {
        guard isAttached else { return }
        isAttached = false
        panel.orderOut(nil)
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        hostView.hostedDisplayLayer.removeFromSuperlayer()
        CATransaction.commit()
        CATransaction.flush()
        panel.contentView = nil
        panel.close()
        Self.emit(
            "host-detached panel-visible=\(panel.isVisible)"
                + " window=\(hostView.window != nil)"
                + " superlayer=\(hostView.hostedDisplayLayer.superlayer != nil)"
        )
    }

    deinit {
        Self.emit("host-owner-deinit")
    }

    private static func size(_ size: CGSize) -> String {
        "\(Int(size.width.rounded()))x\(Int(size.height.rounded()))"
    }

    private static func validSize(_ size: CGSize) -> CGSize? {
        guard size.width.isFinite,
              size.height.isFinite,
              size.width > 0,
              size.height > 0
        else {
            return nil
        }
        return size
    }

    private nonisolated static func emit(_ message: String) {
        FileHandle.standardError.write(
            Data("[native-pip-subtitles] \(message)\n".utf8)
        )
    }
}

struct PiPSubtitleCompositionMetrics: Equatable, Sendable {
    var receivedFrames = 0
    var composedFrames = 0
    var immediatelyDisplayedFrames = 0
    var subtitleVisibleFrames = 0
    var coalescedFrames = 0
    var unsupportedFrames = 0
    var outputPoolMisses = 0
    var outputPixelBufferAllocations = 0
    var outputPixelBufferReuses = 0
    var enqueueFailures = 0
    var discardedStaleCompositions = 0
    var compositionCPUTimeNanoseconds: UInt64 = 0
    var compositionGPUTimeNanoseconds: UInt64 = 0

    var averageCPUTimeMilliseconds: Double {
        guard composedFrames > 0 else { return 0 }
        return Double(compositionCPUTimeNanoseconds) / Double(composedFrames) / 1_000_000
    }

    var averageGPUTimeMilliseconds: Double {
        guard composedFrames > 0 else { return 0 }
        return Double(compositionGPUTimeNanoseconds) / Double(composedFrames) / 1_000_000
    }
}

struct PiPSubtitleCompositionFence: Equatable, Sendable {
    private(set) var revision: UInt64 = 0

    mutating func invalidate() {
        precondition(revision < UInt64.max, "PiP composition revision exhausted")
        revision += 1
    }

    func accepts(_ candidate: UInt64) -> Bool {
        candidate == revision
    }
}

private enum PiPSubtitleCompositorError: LocalizedError {
    case metalUnavailable
    case textureCacheCreation(CVReturn)
    case pipelineCreation(String)
    case outputPoolCreation(CVReturn)
    case outputPoolExhausted(CVReturn)
    case unsupportedSource(PiPSubtitleCompositionFallbackReason)
    case textureCreation
    case commandEncoding

    var errorDescription: String? {
        switch self {
        case .metalUnavailable:
            "Metal is unavailable."
        case let .textureCacheCreation(status):
            "Metal texture-cache creation failed (\(status))."
        case let .pipelineCreation(message):
            "Metal pipeline creation failed: \(message)"
        case let .outputPoolCreation(status):
            "PiP output-pool creation failed (\(status))."
        case let .outputPoolExhausted(status):
            "PiP output-pool checkout failed (\(status))."
        case let .unsupportedSource(reason):
            reason.diagnosticDescription
        case .textureCreation:
            "A PiP Metal texture could not be created."
        case .commandEncoding:
            "The PiP Metal command could not be encoded."
        }
    }
}

/// Production path for burning the current libass output into a
/// PiP-only SDR frame. The normal sample-buffer presenter still receives the
/// original decoded frame. This compositor retains only the latest pending
/// frame and performs no work until `start` is called.
final class PiPSubtitleCompositor: @unchecked Sendable {
    private static let logger = Logger(
        subsystem: "com.illiquid.pip-subtitles",
        category: "compositor"
    )

    private struct SubtitleVertex {
        var position: SIMD2<Float>
        var textureCoordinate: SIMD2<Float>
        var color: SIMD4<Float>
    }

    private final class MetalFrameResources: @unchecked Sendable {
        let outputPixelBuffer: CVPixelBuffer
        let retainedCVTextures: [CVMetalTexture]

        init(
            outputPixelBuffer: CVPixelBuffer,
            retainedCVTextures: [CVMetalTexture]
        ) {
            self.outputPixelBuffer = outputPixelBuffer
            self.retainedCVTextures = retainedCVTextures
        }
    }

    private final class CompositionResultBox: @unchecked Sendable {
        let result: Result<(CVPixelBuffer, UInt64), Error>

        init(_ result: Result<(CVPixelBuffer, UInt64), Error>) {
            self.result = result
        }
    }

    private final class PixelBufferBox: @unchecked Sendable {
        let pixelBuffer: CVPixelBuffer

        init(_ pixelBuffer: CVPixelBuffer) {
            self.pixelBuffer = pixelBuffer
        }
    }

    private enum CompositionFailureMetric {
        case unsupported
        case enqueue
    }

    private enum CompositionFailureDelivery {
        case stale
        case firstSample((@Sendable (Result<Void, Error>) -> Void)?)
        case runtime((@Sendable (Error) -> Void)?)
    }

    let presenter = SampleBufferVideoPresenter()
    var displayLayer: AVSampleBufferDisplayLayer { presenter.displayLayer }
    var renderer: AVSampleBufferVideoRenderer { presenter.renderer }

    private let device: any MTLDevice
    private let commandQueue: any MTLCommandQueue
    private let textureCache: CVMetalTextureCache
    private let bgraPipeline: any MTLRenderPipelineState
    private let nv12Pipeline: any MTLRenderPipelineState
    private let subtitlePipeline: any MTLRenderPipelineState
    private let bitmapSubtitlePipeline: any MTLRenderPipelineState
    private struct TenBitPipelines {
        let video: any MTLRenderPipelineState
        let text: any MTLRenderPipelineState
        let bitmap: any MTLRenderPipelineState
    }
    private let tenBitPipelines: TenBitPipelines?
    private struct HDRPipelines {
        let video: any MTLRenderPipelineState
        let text: any MTLRenderPipelineState
        let bitmap: any MTLRenderPipelineState
        let luma: any MTLRenderPipelineState
        let chroma: any MTLRenderPipelineState
    }
    private let hdrPipelines: HDRPipelines?
    private var hdrLinearTexture: (any MTLTexture)?
    private let sampler: any MTLSamplerState
    private let subtitlePacker: ASSSubtitleFramePacker
    private let workQueue = DispatchQueue(
        label: "com.illiquid.pip-subtitles",
        qos: .userInteractive
    )
    private let stateLock = NSLock()

    private var active = false
    private var workerActive = false
    private var videoAdjustments = VideoAdjustmentState.standard
    private var latestFrame: NativeDecodedVideoFrame?
    private var pendingFrame: NativeDecodedVideoFrame?
    private var pendingFrameDisplaysImmediately = false
    private var firstSampleHandler: (@Sendable (Result<Void, Error>) -> Void)?
    private var runtimeFailureHandler: (@Sendable (Error) -> Void)?
    private var deliveredFirstSample = false
    private var metrics = PiPSubtitleCompositionMetrics()
    private var outputPool: CVPixelBufferPool?
    private var outputPoolObserver: NSObjectProtocol?
    private var outputPoolSize = CGSize.zero
    private var outputPoolPixelFormat: OSType = kCVPixelFormatType_32BGRA
    private var observedOutputBuffers: Set<UInt> = []
    private var preparedSubtitleFrame: ASSPreparedSubtitleFrame?
    private var subtitleTexture: (any MTLTexture)?
    private var subtitleVertexBuffer: (any MTLBuffer)?
    private var subtitleVertexCapacity = 0
    private var lastSourceSize = CGSize.zero
    private var lastEnqueuedGeneration: Int?
    private var compositionFence = PiPSubtitleCompositionFence()
    private var boundSubtitlePipeline: SubtitlePipeline?
    private var subtitlePipelineRevision: UInt64 = 0
    // Work-queue confined. The revision prevents a new pipeline from reusing
    // a prepared frame produced by the preceding source.
    private var preparedSubtitlePipelineRevision: UInt64?

    init(
        subtitles: SubtitlePipeline? = nil,
        memoryBudget: SubtitleMemoryBudget? = nil
    ) throws {
        guard let device = MTLCreateSystemDefaultDevice(),
              let commandQueue = device.makeCommandQueue()
        else {
            throw PiPSubtitleCompositorError.metalUnavailable
        }
        var cache: CVMetalTextureCache?
        let cacheStatus = CVMetalTextureCacheCreate(
            kCFAllocatorDefault,
            nil,
            device,
            nil,
            &cache
        )
        guard cacheStatus == kCVReturnSuccess, let cache else {
            throw PiPSubtitleCompositorError.textureCacheCreation(cacheStatus)
        }

        boundSubtitlePipeline = subtitles
        subtitlePacker = ASSSubtitleFramePacker(
            memoryBudget: memoryBudget,
            memoryOwner: .pictureInPictureStaging
        )
        self.device = device
        self.commandQueue = commandQueue
        textureCache = cache

        do {
            let library = try NativeMetalShaderLibrary.load(device: device)
            guard let videoVertex = library.makeFunction(name: "pip_video_vertex"),
                  let bgraFragment = library.makeFunction(name: "pip_bgra_fragment"),
                  let nv12Fragment = library.makeFunction(name: "pip_nv12_fragment"),
                  let subtitleVertex = library.makeFunction(name: "pip_subtitle_vertex"),
                  let subtitleFragment = library.makeFunction(name: "pip_subtitle_fragment"),
                  let bitmapSubtitleFragment = library.makeFunction(name: "pip_bitmap_subtitle_fragment")
            else {
                throw PiPSubtitleCompositorError.pipelineCreation(
                    "required shader function is unavailable"
                )
            }
            bgraPipeline = try Self.makePipeline(
                device: device,
                vertex: videoVertex,
                fragment: bgraFragment,
                blending: false
            )
            nv12Pipeline = try Self.makePipeline(
                device: device,
                vertex: videoVertex,
                fragment: nv12Fragment,
                blending: false
            )
            subtitlePipeline = try Self.makePipeline(
                device: device,
                vertex: subtitleVertex,
                fragment: subtitleFragment,
                blending: true
            )
            bitmapSubtitlePipeline = try Self.makePipeline(
                device: device, vertex: subtitleVertex, fragment: bitmapSubtitleFragment,
                blending: true, premultiplied: true
            )
            // Failure of the optional ten-bit target must not disable ordinary
            // SDR composition on a device that supports only the existing path.
            tenBitPipelines = try? TenBitPipelines(
                video: Self.makePipeline(device: device, vertex: videoVertex, fragment: nv12Fragment,
                                         blending: false, pixelFormat: .bgr10a2Unorm),
                text: Self.makePipeline(device: device, vertex: subtitleVertex, fragment: subtitleFragment,
                                        blending: true, pixelFormat: .bgr10a2Unorm),
                bitmap: Self.makePipeline(device: device, vertex: subtitleVertex, fragment: bitmapSubtitleFragment,
                                          blending: true, premultiplied: true, pixelFormat: .bgr10a2Unorm)
            )
            if let hdrVideo = library.makeFunction(name: "pip_hdr_video_fragment"),
               let hdrText = library.makeFunction(name: "pip_hdr_text_fragment"),
               let hdrBitmap = library.makeFunction(name: "pip_hdr_bitmap_fragment"),
               let hdrLuma = library.makeFunction(name: "pip_hdr_luma_fragment"),
               let hdrChroma = library.makeFunction(name: "pip_hdr_chroma_fragment") {
                hdrPipelines = try? HDRPipelines(
                    video: Self.makePipeline(device: device, vertex: videoVertex, fragment: hdrVideo, blending: false, pixelFormat: .rgba16Float),
                    text: Self.makePipeline(device: device, vertex: subtitleVertex, fragment: hdrText, blending: true, pixelFormat: .rgba16Float),
                    bitmap: Self.makePipeline(device: device, vertex: subtitleVertex, fragment: hdrBitmap, blending: true, premultiplied: true, pixelFormat: .rgba16Float),
                    luma: Self.makePipeline(device: device, vertex: videoVertex, fragment: hdrLuma, blending: false, pixelFormat: .r16Unorm),
                    chroma: Self.makePipeline(device: device, vertex: videoVertex, fragment: hdrChroma, blending: false, pixelFormat: .rg16Unorm))
            } else { hdrPipelines = nil }
        } catch {
            throw PiPSubtitleCompositorError.pipelineCreation(
                error.localizedDescription
            )
        }

        let samplerDescriptor = MTLSamplerDescriptor()
        samplerDescriptor.minFilter = .linear
        samplerDescriptor.magFilter = .linear
        samplerDescriptor.sAddressMode = .clampToEdge
        samplerDescriptor.tAddressMode = .clampToEdge
        guard let sampler = device.makeSamplerState(descriptor: samplerDescriptor) else {
            throw PiPSubtitleCompositorError.pipelineCreation(
                "sampler creation returned nil"
            )
        }
        self.sampler = sampler
        // AVKit's rounded PiP viewport can differ from the media aspect by a
        // fraction of a point. Fill only this already-composited PiP layer so
        // that rounding cannot expose thin background slivers at either edge.
        presenter.displayLayer.videoGravity = .resizeAspectFill
        presenter.displayLayer.contentsScale = 1
    }

    var isActive: Bool {
        stateLock.withLock { active }
    }

    var latestEligibility: PiPSubtitleCompositionEligibility? {
        stateLock.withLock {
            latestFrame.map(PiPSubtitleCompositionPolicy.eligibility(for:))
        }
    }

    func setSubtitlePipeline(_ pipeline: SubtitlePipeline?) {
        let shouldStartWorker: Bool? = stateLock.withLock {
            guard boundSubtitlePipeline !== pipeline else { return nil }
            boundSubtitlePipeline = pipeline
            subtitlePipelineRevision &+= 1
            compositionFence.invalidate()
            pendingFrameDisplaysImmediately = true
            if active, let latestFrame {
                if pendingFrame != nil {
                    metrics.coalescedFrames += 1
                }
                pendingFrame = latestFrame
                if !workerActive {
                    workerActive = true
                    return true
                }
            }
            return false
        }
        guard let shouldStartWorker else { return }
        workQueue.async { [weak self] in
            guard let self else { return }
            preparedSubtitleFrame = nil
            preparedSubtitlePipelineRevision = nil
            subtitleTexture = nil
            subtitleVertexBuffer = nil
            subtitleVertexCapacity = 0
            subtitlePacker.retireSource()
            if shouldStartWorker {
                consumePendingFrame()
            }
        }
    }

    var subtitlePipelineIdentityForTesting: ObjectIdentifier? {
        stateLock.withLock { boundSubtitlePipeline.map(ObjectIdentifier.init) }
    }

    func receive(_ frame: NativeDecodedVideoFrame) {
        var shouldStartWorker = false
        stateLock.withLock {
            metrics.receivedFrames += 1
            latestFrame = frame
            guard active else { return }
            if pendingFrame != nil {
                metrics.coalescedFrames += 1
            }
            pendingFrame = frame
            if !workerActive {
                workerActive = true
                shouldStartWorker = true
            }
        }
        if shouldStartWorker {
            workQueue.async { [weak self] in
                self?.consumePendingFrame()
            }
        }
    }

    func setVideoAdjustments(_ adjustments: VideoAdjustmentState) {
        stateLock.withLock { videoAdjustments = adjustments; subtitlePipelineRevision &+= 1 }
        refreshLatestFrame()
    }

    func refreshLatestFrame() {
        var shouldStartWorker = false
        stateLock.withLock {
            compositionFence.invalidate()
            guard active, let latestFrame else { return }
            if pendingFrame != nil {
                metrics.coalescedFrames += 1
            }
            pendingFrame = latestFrame
            pendingFrameDisplaysImmediately = true
            if !workerActive {
                workerActive = true
                shouldStartWorker = true
            }
        }
        if shouldStartWorker {
            workQueue.async { [weak self] in
                self?.consumePendingFrame()
            }
        }
    }

    func start(
        onFirstSample: @escaping @Sendable (Result<Void, Error>) -> Void,
        onFailure: @escaping @Sendable (Error) -> Void
    ) {
        emitLifecycle("start-request")
        var shouldStartWorker = false
        stateLock.withLock {
            active = true
            metrics = PiPSubtitleCompositionMetrics()
            firstSampleHandler = onFirstSample
            runtimeFailureHandler = onFailure
            deliveredFirstSample = false
            pendingFrame = latestFrame
            // A preceding PiP session flushes the displayed image. Re-entry
            // while paused can reuse the exact same decoded generation, so
            // the first cached frame must be presented independently of the
            // synchronizer clock instead of waiting for a future frame.
            pendingFrameDisplaysImmediately = pendingFrame != nil
            lastEnqueuedGeneration = nil
            if pendingFrame != nil, !workerActive {
                workerActive = true
                shouldStartWorker = true
            }
        }
        if shouldStartWorker {
            workQueue.async { [weak self] in
                self?.consumePendingFrame()
            }
        }
    }

    func stop() {
        emitLifecycle("stop-request")
        stateLock.withLock {
            compositionFence.invalidate()
            active = false
            pendingFrame = nil
            pendingFrameDisplaysImmediately = false
            firstSampleHandler = nil
            runtimeFailureHandler = nil
            deliveredFirstSample = false
        }
        workQueue.async { [weak self] in
            guard let self else { return }
            presenter.flush(removeDisplayedImage: true)
            emitMetrics()
        }
    }

    func invalidatePendingFrames() {
        stateLock.withLock {
            compositionFence.invalidate()
            latestFrame = nil
            pendingFrame = nil
            pendingFrameDisplaysImmediately = false
            lastEnqueuedGeneration = nil
        }
    }

    @discardableResult
    func setViewportSize(_ viewportSize: CGSize?) -> CGSize? {
        let fallback = stateLock.withLock { lastSourceSize }
        let size = viewportSize.flatMap { candidate -> CGSize? in
            guard candidate.width.isFinite,
                  candidate.height.isFinite,
                  candidate.width > 0,
                  candidate.height > 0
            else {
                return nil
            }
            return candidate
        } ?? fallback
        guard size.width > 0, size.height > 0 else { return nil }
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        presenter.displayLayer.contentsScale = 1
        presenter.displayLayer.bounds = CGRect(origin: .zero, size: size)
        CATransaction.commit()
        return size
    }

    func metricsSnapshot() -> PiPSubtitleCompositionMetrics {
        stateLock.withLock { metrics }
    }

    func composedPixelBufferForTesting(
        _ frame: NativeDecodedVideoFrame
    ) async throws -> CVPixelBuffer {
        let box: PixelBufferBox = try await withCheckedThrowingContinuation { continuation in
            workQueue.async { [weak self] in
                guard let self else {
                    continuation.resume(
                        throwing: PiPSubtitleCompositorError.commandEncoding
                    )
                    return
                }
                do {
                    try compose(frame) { result in
                        continuation.resume(with: result.map {
                            PixelBufferBox($0.0)
                        })
                    }
                } catch {
                    continuation.resume(throwing: error)
                }
            }
        }
        return box.pixelBuffer
    }

    private func consumePendingFrame() {
        let work: (
            frame: NativeDecodedVideoFrame,
            displayImmediately: Bool,
            revision: UInt64
        )? =
            stateLock.withLock {
            guard active else {
                workerActive = false
                return nil
            }
            let frame = pendingFrame
            pendingFrame = nil
            let displayImmediately = pendingFrameDisplaysImmediately
            pendingFrameDisplaysImmediately = false
            if frame == nil {
                workerActive = false
            }
            return frame.map { ($0, displayImmediately, compositionFence.revision) }
        }
        guard let work else { return }

        do {
            try compose(work.frame) { [weak self] result in
                guard let self else { return }
                let resultBox = CompositionResultBox(result)
                workQueue.async {
                    self.finishComposition(
                        frame: work.frame,
                        forceDisplayImmediately: work.displayImmediately,
                        revision: work.revision,
                        result: resultBox.result
                    )
                }
            }
        } catch PiPSubtitleCompositorError.outputPoolExhausted(kCVReturnWouldExceedAllocationThreshold) {
            // Renderer-held buffers are backpressure, not a format failure.
            // Keep one pending frame and resume on Core Video's notification.
            stateLock.withLock {
                if active, compositionFence.accepts(work.revision), pendingFrame == nil {
                    pendingFrame = work.frame
                    pendingFrameDisplaysImmediately = work.displayImmediately
                }
                workerActive = false
            }
        } catch {
            reportCompositionFailure(
                error,
                revision: work.revision,
                metric: .unsupported
            )
            workQueue.async { [weak self] in
                self?.consumePendingFrame()
            }
        }
    }

    private func finishComposition(
        frame: NativeDecodedVideoFrame,
        forceDisplayImmediately: Bool,
        revision: UInt64,
        result: Result<(CVPixelBuffer, UInt64), Error>
    ) {
        switch result {
        case let .success((pixelBuffer, gpuNanoseconds)):
            let outputSize = CGSize(
                width: CVPixelBufferGetWidth(pixelBuffer),
                height: CVPixelBufferGetHeight(pixelBuffer)
            )
            let outputFrame = NativeDecodedVideoFrame(
                pixelBuffer: pixelBuffer,
                planarOwnershipToken: nil,
                presentationTime: frame.presentationTime,
                duration: frame.duration,
                generation: frame.generation,
                codedSize: outputSize,
                displaySize: outputSize,
                pixelAspectRatio: CGSize(width: 1, height: 1),
                rotationDegrees: 0,
                colorPrimaries: frame.colorPrimaries,
                transferCharacteristic: frame.transferCharacteristic,
                matrixCoefficients: CVPixelBufferIsPlanar(pixelBuffer) ? frame.matrixCoefficients : nil,
                isFullRange: CVPixelBufferIsPlanar(pixelBuffer)
                    ? CVPixelBufferGetPixelFormatType(pixelBuffer) == kCVPixelFormatType_420YpCbCr10BiPlanarFullRange : true,
                hasMasteringDisplayMetadata: false,
                hasContentLightMetadata: false,
                sourceComponentDepth: CVPixelBufferIsPlanar(pixelBuffer) || CVPixelBufferGetPixelFormatType(pixelBuffer) == kCVPixelFormatType_ARGB2101010LEPacked ? 10 : 8,
                ffmpegPixelFormat: CVPixelBufferIsPlanar(pixelBuffer) ? "pip-composited-hdr-p010" : CVPixelBufferGetPixelFormatType(pixelBuffer) == kCVPixelFormatType_ARGB2101010LEPacked
                    ? "pip-composited-bgr10a2" : "pip-composited-bgra",
                isHardwareDecoded: false,
                isCopiedHardwarePath: true,
                isNearZeroCopy: false
            )
            do {
                let accepted = try stateLock.withLock { () throws -> Bool in
                    guard active, compositionFence.accepts(revision) else {
                        metrics.discardedStaleCompositions += 1
                        return false
                    }
                    let changed = lastEnqueuedGeneration != frame.generation
                        || forceDisplayImmediately
                    lastEnqueuedGeneration = frame.generation
                    try presenter.enqueue(
                        outputFrame,
                        displayImmediately: changed
                    )
                    metrics.composedFrames += 1
                    metrics.immediatelyDisplayedFrames += changed ? 1 : 0
                    metrics.compositionGPUTimeNanoseconds &+= gpuNanoseconds
                    return true
                }
                guard accepted else {
                    consumePendingFrame()
                    return
                }
                finishFirstSample(.success(()))
            } catch {
                reportCompositionFailure(
                    error,
                    revision: revision,
                    metric: .enqueue
                )
            }
        case let .failure(error):
            reportCompositionFailure(
                error,
                revision: revision,
                metric: .enqueue
            )
        }
        consumePendingFrame()
    }

    private func finishFirstSample(_ result: Result<Void, Error>) {
        let handler: (@Sendable (Result<Void, Error>) -> Void)? = stateLock.withLock {
            guard !deliveredFirstSample else { return nil }
            deliveredFirstSample = true
            let handler = firstSampleHandler
            firstSampleHandler = nil
            return handler
        }
        if handler != nil {
            switch result {
            case .success:
                emitLifecycle("first-sample")
            case let .failure(error):
                emitLifecycle("first-sample-failed error=\(error.localizedDescription)")
            }
        }
        handler?(result)
    }

    private func reportCompositionFailure(
        _ error: Error,
        revision: UInt64,
        metric: CompositionFailureMetric
    ) {
        let delivery: CompositionFailureDelivery = stateLock.withLock {
            guard active, compositionFence.accepts(revision) else {
                metrics.discardedStaleCompositions += 1
                return .stale
            }
            switch metric {
            case .unsupported:
                metrics.unsupportedFrames += 1
            case .enqueue:
                metrics.enqueueFailures += 1
            }
            if deliveredFirstSample {
                let handler = runtimeFailureHandler
                runtimeFailureHandler = nil
                return .runtime(handler)
            }
            deliveredFirstSample = true
            runtimeFailureHandler = nil
            let handler = firstSampleHandler
            firstSampleHandler = nil
            return .firstSample(handler)
        }

        switch delivery {
        case .stale:
            break
        case let .firstSample(handler):
            if handler != nil {
                emitLifecycle(
                    "first-sample-failed error=\(error.localizedDescription)"
                )
            }
            handler?(.failure(error))
        case let .runtime(handler):
            handler?(error)
        }
    }

    private func compose(
        _ frame: NativeDecodedVideoFrame,
        completion: @escaping @Sendable (
            Result<(CVPixelBuffer, UInt64), Error>
        ) -> Void
    ) throws {
        let cpuStart = DispatchTime.now().uptimeNanoseconds
        let sourceWidth = CVPixelBufferGetWidth(frame.pixelBuffer)
        let sourceHeight = CVPixelBufferGetHeight(frame.pixelBuffer)
        guard sourceWidth > 0, sourceHeight > 0 else {
            throw PiPSubtitleCompositorError.textureCreation
        }
        let displaySize = Self.validDisplaySize(
            frame.displaySize,
            fallback: CGSize(width: sourceWidth, height: sourceHeight)
        )
        var adjustments = stateLock.withLock { videoAdjustments }
        // System PiP owns its window aspect. Encode the selected crop/aspect
        // into the frame; Fit/Fill remains the main-window sizing preference.
        adjustments.scaleMode = .fit
        let aspect = VideoPresentationGeometry.ratio(adjustments.aspectRatio) ?? displaySize.width / displaySize.height
        var outputSize = CGSize(width: displaySize.height * aspect, height: displaySize.height)
        if let crop = VideoPresentationGeometry.ratio(adjustments.crop) {
            if crop < aspect { outputSize.width = outputSize.height * crop }
            else { outputSize.height = outputSize.width / crop }
        }
        let scale = min(1, 8192 / max(outputSize.width, outputSize.height),
            sqrt(33_554_432 / max(outputSize.width * outputSize.height, 1)))
        let width = max(2, Int(outputSize.width * scale) / 2 * 2)
        let height = max(2, Int(outputSize.height * scale) / 2 * 2)
        let geometry = VideoPresentationGeometry(sourceSize: displaySize,
            bounds: CGRect(x: 0, y: 0, width: width, height: height), adjustments: adjustments)
        stateLock.withLock {
            lastSourceSize = CGSize(width: width, height: height)
        }
        if presenter.displayLayer.bounds.isEmpty {
            setViewportSize(nil)
        }

        let compositionMode: PiPSubtitleCompositionMode
        switch PiPSubtitleCompositionPolicy.eligibility(for: frame) {
        case let .supported(mode): compositionMode = mode
        case let .videoOnly(reason): throw PiPSubtitleCompositorError.unsupportedSource(reason)
        }
        let tenBit = compositionMode.usesTenBitOutput
        let hdr = compositionMode.isHDR
        if (hdr && hdrPipelines == nil) || (tenBit && !hdr && tenBitPipelines == nil) {
            throw PiPSubtitleCompositorError.pipelineCreation("The required high-precision composition target is unavailable")
        }
        // One reusable HDR intermediate, at most 64 MiB (includes UHD 4K).
        guard !hdr || width * height <= 8_388_608 else {
            throw PiPSubtitleCompositorError.pipelineCreation("HDR PiP composition exceeds its 64 MiB working-texture limit")
        }
        let outputFormat = hdr ? CVPixelBufferGetPixelFormatType(frame.pixelBuffer)
            : tenBit ? kCVPixelFormatType_ARGB2101010LEPacked : kCVPixelFormatType_32BGRA
        let output = try checkoutOutputPixelBuffer(width: width, height: height, pixelFormat: outputFormat)
        applySDRColorAttachments(from: frame.pixelBuffer, to: output)
        if hdr {
            // Signal tags describe the actual generated pixels. Source static
            // luminance statistics are not copied onto the composited image.
            CVBufferSetAttachment(output, kCVImageBufferTransferFunctionKey,
                frame.transferCharacteristic == 18 ? kCVImageBufferTransferFunction_ITU_R_2100_HLG
                    : kCVImageBufferTransferFunction_SMPTE_ST_2084_PQ, .shouldPropagate)
            CVBufferSetAttachment(output, kCVImageBufferColorPrimariesKey,
                frame.colorPrimaries == 1 ? kCVImageBufferColorPrimaries_ITU_R_709_2
                    : kCVImageBufferColorPrimaries_ITU_R_2020, .shouldPropagate)
            let matrix = frame.matrixCoefficients == 9 ? kCVImageBufferYCbCrMatrix_ITU_R_2020
                : frame.matrixCoefficients == 5 || frame.matrixCoefficients == 6
                    ? kCVImageBufferYCbCrMatrix_ITU_R_601_4 : kCVImageBufferYCbCrMatrix_ITU_R_709_2
            CVBufferSetAttachment(output, kCVImageBufferYCbCrMatrixKey, matrix, .shouldPropagate)
        }
        let outputCVTexture = try makeCVTexture(pixelBuffer: output,
            pixelFormat: hdr ? .r16Unorm : tenBit ? .bgr10a2Unorm : .bgra8Unorm,
            width: width, height: height, plane: 0)
        let outputTexture: any MTLTexture
        if hdr {
            if hdrLinearTexture?.width != width || hdrLinearTexture?.height != height {
                let descriptor = MTLTextureDescriptor.texture2DDescriptor(pixelFormat: .rgba16Float,
                    width: width, height: height, mipmapped: false)
                descriptor.usage = [.renderTarget, .shaderRead]
                descriptor.storageMode = .private
                hdrLinearTexture = device.makeTexture(descriptor: descriptor)
            }
            guard let linear = hdrLinearTexture else { throw PiPSubtitleCompositorError.textureCreation }
            outputTexture = linear
        } else {
            hdrLinearTexture = nil
            guard let texture = CVMetalTextureGetTexture(outputCVTexture) else { throw PiPSubtitleCompositorError.textureCreation }
            outputTexture = texture
        }

        let sourceTextures: [CVMetalTexture]
        let videoPipeline: any MTLRenderPipelineState
        switch compositionMode {
        case .bgra:
            sourceTextures = [try makeCVTexture(
                pixelBuffer: frame.pixelBuffer,
                pixelFormat: .bgra8Unorm,
                width: sourceWidth,
                height: sourceHeight,
                plane: 0
            )]
            videoPipeline = bgraPipeline
        case .nv12VideoRange, .nv12FullRange, .p010VideoRange, .p010FullRange, .hdrP010VideoRange, .hdrP010FullRange:
            sourceTextures = [
                try makeCVTexture(
                    pixelBuffer: frame.pixelBuffer,
                    pixelFormat: tenBit ? .r16Unorm : .r8Unorm,
                    width: sourceWidth,
                    height: sourceHeight,
                    plane: 0
                ),
                try makeCVTexture(
                    pixelBuffer: frame.pixelBuffer,
                    pixelFormat: tenBit ? .rg16Unorm : .rg8Unorm,
                    width: CVPixelBufferGetWidthOfPlane(frame.pixelBuffer, 1),
                    height: CVPixelBufferGetHeightOfPlane(frame.pixelBuffer, 1),
                    plane: 1
                ),
            ]
            videoPipeline = hdr ? hdrPipelines!.video : tenBit ? tenBitPipelines!.video : nv12Pipeline
        }

        let subtitleBinding = stateLock.withLock {
            (
                pipeline: boundSubtitlePipeline,
                revision: subtitlePipelineRevision
            )
        }
        if preparedSubtitlePipelineRevision != subtitleBinding.revision {
            preparedSubtitleFrame = nil
            preparedSubtitlePipelineRevision = subtitleBinding.revision
            subtitlePacker.retireSource()
        }
        if let subtitles = subtitleBinding.pipeline {
            let subtitleSnapshot = subtitles.pictureInPictureSubtitleSnapshot(
                at: frame.presentationTime,
                viewport: geometry.imageRect,
                videoSize: displaySize
            )
            if subtitleSnapshot.changed || preparedSubtitleFrame == nil {
                preparedSubtitleFrame = subtitlePacker.prepare(
                    regions: subtitleSnapshot.regions,
                    canvasSize: CGSize(width: width, height: height),
                    strategy: .metalR8Atlas
                )
            }
        } else {
            preparedSubtitleFrame = nil
        }
        let preparedSubtitleFrame = preparedSubtitleFrame
        if preparedSubtitleFrame?.quads.isEmpty == false {
            stateLock.withLock {
                metrics.subtitleVisibleFrames += 1
            }
        }

        guard let commandBuffer = commandQueue.makeCommandBuffer() else {
            throw PiPSubtitleCompositorError.commandEncoding
        }
        let videoPass = MTLRenderPassDescriptor()
        videoPass.colorAttachments[0].texture = outputTexture
        videoPass.colorAttachments[0].loadAction = .clear
        videoPass.colorAttachments[0].storeAction = .store
        videoPass.colorAttachments[0].clearColor = MTLClearColorMake(0, 0, 0, 1)
        guard let videoEncoder = commandBuffer.makeRenderCommandEncoder(
            descriptor: videoPass
        ) else {
            throw PiPSubtitleCompositorError.commandEncoding
        }
        videoEncoder.setRenderPipelineState(videoPipeline)
        let coordinates = PiPVideoMapping.textureCoordinates(
            codedSize: CGSize(width: sourceWidth, height: sourceHeight),
            cleanAperture: frame.cleanAperture,
            rotationDegrees: frame.rotationDegrees,
            mirrored: frame.isHorizontallyMirrored,
            displayCrop: CGRect(x: -geometry.imageRect.minX / geometry.imageRect.width,
                y: -geometry.imageRect.minY / geometry.imageRect.height,
                width: Double(width) / geometry.imageRect.width,
                height: Double(height) / geometry.imageRect.height)
        )
        coordinates.withUnsafeBytes { bytes in
            videoEncoder.setVertexBytes(bytes.baseAddress!, length: bytes.count, index: 0)
        }
        for (index, cvTexture) in sourceTextures.enumerated() {
            guard let texture = CVMetalTextureGetTexture(cvTexture) else {
                videoEncoder.endEncoding()
                throw PiPSubtitleCompositorError.textureCreation
            }
            videoEncoder.setFragmentTexture(texture, index: index)
        }
        videoEncoder.setFragmentSamplerState(sampler, index: 0)
        var sourceEncoding: UInt32 =
            (compositionMode.isFullRange ? 1 : 0) | (tenBit ? 2 : 0)
        videoEncoder.setFragmentBytes(
            &sourceEncoding,
            length: MemoryLayout<UInt32>.size,
            index: 0
        )
        var coefficients = PiPVideoMapping.colorCoefficients(matrix: frame.matrixCoefficients)
        videoEncoder.setFragmentBytes(
            &coefficients, length: MemoryLayout<SIMD4<Float>>.stride, index: 1
        )
        var transfer = UInt32(clamping: frame.transferCharacteristic ?? 16)
        var primaries = UInt32(clamping: frame.colorPrimaries ?? 9)
        if hdr {
            videoEncoder.setFragmentBytes(&transfer, length: 4, index: 2)
            videoEncoder.setFragmentBytes(&primaries, length: 4, index: 3)
        }
        videoEncoder.drawPrimitives(type: .triangle, vertexStart: 0, vertexCount: 6)
        videoEncoder.endEncoding()

        if let preparedSubtitleFrame,
           !preparedSubtitleFrame.quads.isEmpty
        {
            try encodeSubtitles(
                preparedSubtitleFrame,
                target: outputTexture,
                commandBuffer: commandBuffer,
                hdrPrimaries: hdr ? primaries : nil
            )
        }
        var outputTextures = [outputCVTexture]
        if hdr, let hdrPipelines {
            let chroma = try makeCVTexture(pixelBuffer: output, pixelFormat: .rg16Unorm,
                width: CVPixelBufferGetWidthOfPlane(output, 1), height: CVPixelBufferGetHeightOfPlane(output, 1), plane: 1)
            outputTextures.append(chroma)
            let identity = PiPVideoMapping.textureCoordinates(codedSize: CGSize(width: width, height: height),
                cleanAperture: nil, rotationDegrees: 0, mirrored: false)
            for (texture, pipeline) in zip(outputTextures, [hdrPipelines.luma, hdrPipelines.chroma]) {
                let pass = MTLRenderPassDescriptor()
                pass.colorAttachments[0].texture = CVMetalTextureGetTexture(texture)
                pass.colorAttachments[0].loadAction = .dontCare
                pass.colorAttachments[0].storeAction = .store
                guard let encoder = commandBuffer.makeRenderCommandEncoder(descriptor: pass) else {
                    throw PiPSubtitleCompositorError.commandEncoding
                }
                encoder.setRenderPipelineState(pipeline)
                identity.withUnsafeBytes { encoder.setVertexBytes($0.baseAddress!, length: $0.count, index: 0) }
                encoder.setFragmentTexture(outputTexture, index: 0)
                encoder.setFragmentBytes(&sourceEncoding, length: 4, index: 0)
                encoder.setFragmentBytes(&coefficients, length: MemoryLayout<SIMD4<Float>>.stride, index: 1)
                encoder.setFragmentBytes(&transfer, length: 4, index: 2)
                encoder.setFragmentBytes(&primaries, length: 4, index: 3)
                encoder.drawPrimitives(type: .triangle, vertexStart: 0, vertexCount: 6)
                encoder.endEncoding()
            }
        }

        let resources = MetalFrameResources(
            outputPixelBuffer: output,
            retainedCVTextures: sourceTextures + outputTextures
        )
        let cpuNanoseconds = DispatchTime.now().uptimeNanoseconds - cpuStart
        stateLock.withLock {
            metrics.compositionCPUTimeNanoseconds &+= cpuNanoseconds
        }
        commandBuffer.addCompletedHandler { commandBuffer in
            // Metal's callback runs on an external queue. Rejoin the resource
            // owner's queue before reading the retained resources or completing
            // the frame, with an explicit synchronization boundary.
            self.workQueue.async {
                _ = resources.retainedCVTextures
                guard commandBuffer.status != .error else {
                    completion(.failure(
                        commandBuffer.error
                            ?? PiPSubtitleCompositorError.commandEncoding
                    ))
                    return
                }
                let gpuDuration = commandBuffer.gpuEndTime - commandBuffer.gpuStartTime
                let gpuNanoseconds: UInt64 = if gpuDuration.isFinite, gpuDuration > 0 {
                    UInt64(gpuDuration * 1_000_000_000)
                } else {
                    0
                }
                completion(.success((resources.outputPixelBuffer, gpuNanoseconds)))
            }
        }
        commandBuffer.commit()
    }

    private func encodeSubtitles(
        _ frame: ASSPreparedSubtitleFrame,
        target: any MTLTexture,
        commandBuffer: any MTLCommandBuffer,
        hdrPrimaries: UInt32? = nil
    ) throws {
        let textureWidth = Int(frame.textureSize.width)
        let textureHeight = Int(frame.textureSize.height)
        guard textureWidth > 0, textureHeight > 0 else { return }
        let pixelFormat: MTLPixelFormat = frame.strategy == .metalBGRA ? .bgra8Unorm : .r8Unorm
        if subtitleTexture == nil
            || subtitleTexture!.width < textureWidth
            || subtitleTexture!.height < textureHeight
            || subtitleTexture!.pixelFormat != pixelFormat
        {
            let descriptor = MTLTextureDescriptor.texture2DDescriptor(
                pixelFormat: pixelFormat,
                width: textureWidth,
                height: textureHeight,
                mipmapped: false
            )
            descriptor.usage = [.shaderRead]
            descriptor.storageMode = .shared
            subtitleTexture = device.makeTexture(descriptor: descriptor)
        }
        guard let subtitleTexture else {
            throw PiPSubtitleCompositorError.textureCreation
        }
        frame.pixels.withUnsafeBytes { bytes in
            guard let baseAddress = bytes.baseAddress else { return }
            subtitleTexture.replace(
                region: MTLRegionMake2D(0, 0, textureWidth, textureHeight),
                mipmapLevel: 0,
                withBytes: baseAddress,
                bytesPerRow: frame.bytesPerRow
            )
        }

        let vertices = subtitleVertices(frame, texture: subtitleTexture)
        let requiredBytes = vertices.count * MemoryLayout<SubtitleVertex>.stride
        if subtitleVertexBuffer == nil || subtitleVertexCapacity < requiredBytes {
            subtitleVertexCapacity = max(requiredBytes, max(subtitleVertexCapacity * 2, 4_096))
            subtitleVertexBuffer = device.makeBuffer(
                length: subtitleVertexCapacity,
                options: .storageModeShared
            )
        }
        guard let subtitleVertexBuffer else {
            throw PiPSubtitleCompositorError.commandEncoding
        }
        vertices.withUnsafeBytes { bytes in
            guard let baseAddress = bytes.baseAddress else { return }
            subtitleVertexBuffer.contents().copyMemory(
                from: baseAddress,
                byteCount: requiredBytes
            )
        }

        let subtitlePass = MTLRenderPassDescriptor()
        subtitlePass.colorAttachments[0].texture = target
        subtitlePass.colorAttachments[0].loadAction = .load
        subtitlePass.colorAttachments[0].storeAction = .store
        guard let encoder = commandBuffer.makeRenderCommandEncoder(
            descriptor: subtitlePass
        ) else {
            throw PiPSubtitleCompositorError.commandEncoding
        }
        var viewport = SIMD2<Float>(
            Float(max(frame.canvasSize.width, 1)),
            Float(max(frame.canvasSize.height, 1))
        )
        if var primaries = hdrPrimaries, let hdrPipelines {
            encoder.setRenderPipelineState(frame.strategy == .metalBGRA ? hdrPipelines.bitmap : hdrPipelines.text)
            encoder.setFragmentBytes(&primaries, length: 4, index: 3)
        } else if target.pixelFormat == .bgr10a2Unorm, let tenBitPipelines {
            encoder.setRenderPipelineState(frame.strategy == .metalBGRA ? tenBitPipelines.bitmap : tenBitPipelines.text)
        } else {
            encoder.setRenderPipelineState(frame.strategy == .metalBGRA ? bitmapSubtitlePipeline : subtitlePipeline)
        }
        encoder.setVertexBuffer(subtitleVertexBuffer, offset: 0, index: 0)
        encoder.setVertexBytes(
            &viewport,
            length: MemoryLayout<SIMD2<Float>>.size,
            index: 1
        )
        encoder.setFragmentTexture(subtitleTexture, index: 0)
        encoder.setFragmentSamplerState(sampler, index: 0)
        encoder.drawPrimitives(
            type: .triangle,
            vertexStart: 0,
            vertexCount: vertices.count
        )
        encoder.endEncoding()
    }

    private func subtitleVertices(
        _ frame: ASSPreparedSubtitleFrame,
        texture: any MTLTexture
    ) -> [SubtitleVertex] {
        var vertices: [SubtitleVertex] = []
        vertices.reserveCapacity(frame.quads.count * 6)
        for quad in frame.quads {
            let alpha = Float(255 - UInt8(quad.color & 0xff)) / 255
            let color = SIMD4<Float>(
                Float((quad.color >> 24) & 0xff) / 255,
                Float((quad.color >> 16) & 0xff) / 255,
                Float((quad.color >> 8) & 0xff) / 255,
                alpha
            )
            let x0 = Float(quad.destination.minX)
            let y0 = Float(quad.destination.minY)
            let x1 = Float(quad.destination.maxX)
            let y1 = Float(quad.destination.maxY)
            let u0 = Float(quad.source.minX) / Float(texture.width)
            let v0 = Float(quad.source.minY) / Float(texture.height)
            let u1 = Float(quad.source.maxX) / Float(texture.width)
            let v1 = Float(quad.source.maxY) / Float(texture.height)
            let topLeft = SubtitleVertex(
                position: SIMD2(x0, y0),
                textureCoordinate: SIMD2(u0, v0),
                color: color
            )
            let bottomLeft = SubtitleVertex(
                position: SIMD2(x0, y1),
                textureCoordinate: SIMD2(u0, v1),
                color: color
            )
            let topRight = SubtitleVertex(
                position: SIMD2(x1, y0),
                textureCoordinate: SIMD2(u1, v0),
                color: color
            )
            let bottomRight = SubtitleVertex(
                position: SIMD2(x1, y1),
                textureCoordinate: SIMD2(u1, v1),
                color: color
            )
            vertices += [topLeft, bottomLeft, topRight, topRight, bottomLeft, bottomRight]
        }
        return vertices
    }

    private func checkoutOutputPixelBuffer(
        width: Int,
        height: Int,
        pixelFormat: OSType = kCVPixelFormatType_32BGRA
    ) throws -> CVPixelBuffer {
        if outputPool == nil
            || outputPoolSize != CGSize(width: width, height: height)
            || outputPoolPixelFormat != pixelFormat
        {
            let attributes: [CFString: Any] = [
                kCVPixelBufferWidthKey: width,
                kCVPixelBufferHeightKey: height,
                kCVPixelBufferPixelFormatTypeKey: pixelFormat,
                kCVPixelBufferMetalCompatibilityKey: true,
                kCVPixelBufferIOSurfacePropertiesKey: [:],
            ]
            var createdPool: CVPixelBufferPool?
            let status = CVPixelBufferPoolCreate(
                kCFAllocatorDefault,
                nil,
                attributes as CFDictionary,
                &createdPool
            )
            guard status == kCVReturnSuccess, let createdPool else {
                throw PiPSubtitleCompositorError.outputPoolCreation(status)
            }
            if let outputPoolObserver {
                NotificationCenter.default.removeObserver(outputPoolObserver)
            }
            outputPool = createdPool
            outputPoolObserver = NotificationCenter.default.addObserver(
                forName: NSNotification.Name(kCVPixelBufferPoolFreeBufferNotification as String),
                object: createdPool,
                queue: nil
            ) { [weak self] _ in
                self?.workQueue.async { [weak self] in
                    guard let self else { return }
                    let shouldResume = stateLock.withLock {
                        guard active, !workerActive, pendingFrame != nil else { return false }
                        workerActive = true
                        return true
                    }
                    if shouldResume { consumePendingFrame() }
                }
            }
            outputPoolSize = CGSize(width: width, height: height)
            outputPoolPixelFormat = pixelFormat
            observedOutputBuffers = []
        }
        guard let outputPool else {
            throw PiPSubtitleCompositorError.outputPoolCreation(
                kCVReturnInvalidArgument
            )
        }
        let allocationAttributes = [
            kCVPixelBufferPoolAllocationThresholdKey: 12,
        ] as CFDictionary
        var output: CVPixelBuffer?
        let status = CVPixelBufferPoolCreatePixelBufferWithAuxAttributes(
            kCFAllocatorDefault,
            outputPool,
            allocationAttributes,
            &output
        )
        guard status == kCVReturnSuccess, let output else {
            stateLock.withLock {
                metrics.outputPoolMisses += 1
            }
            throw PiPSubtitleCompositorError.outputPoolExhausted(status)
        }
        let identity = UInt(bitPattern: Unmanaged.passUnretained(output).toOpaque())
        stateLock.withLock {
            if observedOutputBuffers.insert(identity).inserted {
                metrics.outputPixelBufferAllocations += 1
            } else {
                metrics.outputPixelBufferReuses += 1
            }
        }
        return output
    }

    deinit {
        if let outputPoolObserver { NotificationCenter.default.removeObserver(outputPoolObserver) }
    }

    private func makeCVTexture(
        pixelBuffer: CVPixelBuffer,
        pixelFormat: MTLPixelFormat,
        width: Int,
        height: Int,
        plane: Int
    ) throws -> CVMetalTexture {
        var texture: CVMetalTexture?
        let status = CVMetalTextureCacheCreateTextureFromImage(
            kCFAllocatorDefault,
            textureCache,
            pixelBuffer,
            nil,
            pixelFormat,
            width,
            height,
            plane,
            &texture
        )
        guard status == kCVReturnSuccess, let texture else {
            throw PiPSubtitleCompositorError.textureCreation
        }
        return texture
    }

    private func applySDRColorAttachments(from source: CVPixelBuffer, to pixelBuffer: CVPixelBuffer) {
        CVBufferSetAttachment(
            pixelBuffer,
            kCVImageBufferColorPrimariesKey,
            CVBufferCopyAttachment(source, kCVImageBufferColorPrimariesKey, nil)
                ?? kCVImageBufferColorPrimaries_ITU_R_709_2,
            .shouldPropagate
        )
        CVBufferSetAttachment(
            pixelBuffer,
            kCVImageBufferTransferFunctionKey,
            CVBufferCopyAttachment(source, kCVImageBufferTransferFunctionKey, nil)
                ?? kCVImageBufferTransferFunction_ITU_R_709_2,
            .shouldPropagate
        )
        // Pixels are now full-range RGB. Do not tag them as source YCbCr.
        CVBufferRemoveAttachment(pixelBuffer, kCVImageBufferYCbCrMatrixKey)
    }

    private static func validDisplaySize(
        _ candidate: CGSize,
        fallback: CGSize
    ) -> CGSize {
        guard candidate.width.isFinite,
              candidate.height.isFinite,
              candidate.width > 0,
              candidate.height > 0,
              candidate.width <= 16_384,
              candidate.height <= 16_384
        else {
            return fallback
        }
        return candidate
    }

    private func emitMetrics() {
        let snapshot = metricsSnapshot()
        let message = [
            "[native-pip-subtitles]",
            "received=\(snapshot.receivedFrames)",
            "composed=\(snapshot.composedFrames)",
            "immediate=\(snapshot.immediatelyDisplayedFrames)",
            "visible=\(snapshot.subtitleVisibleFrames)",
            "coalesced=\(snapshot.coalescedFrames)",
            "unsupported=\(snapshot.unsupportedFrames)",
            "pool-allocations=\(snapshot.outputPixelBufferAllocations)",
            "pool-reuses=\(snapshot.outputPixelBufferReuses)",
            "pool-misses=\(snapshot.outputPoolMisses)",
            "enqueue-failures=\(snapshot.enqueueFailures)",
            "stale-compositions=\(snapshot.discardedStaleCompositions)",
            String(format: "cpu-ms-per-frame=%.4f", snapshot.averageCPUTimeMilliseconds),
            String(format: "gpu-ms-per-frame=%.4f", snapshot.averageGPUTimeMilliseconds),
        ].joined(separator: " ")
        FileHandle.standardError.write(Data("\(message)\n".utf8))
        Self.logger.notice("\(message, privacy: .public)")
    }

    private func emitLifecycle(_ event: String) {
        FileHandle.standardError.write(
            Data("[native-pip-subtitles] \(event)\n".utf8)
        )
    }

    private static func makePipeline(
        device: any MTLDevice,
        vertex: any MTLFunction,
        fragment: any MTLFunction,
        blending: Bool,
        premultiplied: Bool = false,
        pixelFormat: MTLPixelFormat = .bgra8Unorm
    ) throws -> any MTLRenderPipelineState {
        let descriptor = MTLRenderPipelineDescriptor()
        descriptor.vertexFunction = vertex
        descriptor.fragmentFunction = fragment
        descriptor.colorAttachments[0].pixelFormat = pixelFormat
        descriptor.colorAttachments[0].isBlendingEnabled = blending
        if blending {
            descriptor.colorAttachments[0].sourceRGBBlendFactor = premultiplied ? .one : .sourceAlpha
            descriptor.colorAttachments[0].destinationRGBBlendFactor = .oneMinusSourceAlpha
            descriptor.colorAttachments[0].sourceAlphaBlendFactor = .one
            descriptor.colorAttachments[0].destinationAlphaBlendFactor = .oneMinusSourceAlpha
        }
        return try device.makeRenderPipelineState(descriptor: descriptor)
    }

}

import CoreGraphics
import Foundation
import Metal
import QuartzCore
import Synchronization

enum SubtitleCompositionStrategy: String, Sendable {
    case metalR8Atlas = "metal-r8"
    case metalBGRA = "metal-bgra"
}

enum MetalASSFailureReason: String, Error, Sendable {
    case deviceInitialization = "device-initialization"
    case pipelineCreation = "pipeline-creation"
    case invalidBackingGeometry = "invalid-backing-geometry"
    case drawableAcquisition = "drawable-acquisition"
    case textureAllocation = "texture-allocation"
    case bufferAllocation = "buffer-allocation"
    case stagingAllocation = "staging-allocation"
    case commandBufferCreation = "command-buffer-creation"
    case commandEncoderCreation = "command-encoder-creation"
    case commandBufferExecution = "command-buffer-execution"
    case requiredClearSubmission = "required-clear-submission"
    case unsupportedConfiguration = "unsupported-configuration"
}

struct MetalASSRendererError: Error, LocalizedError, Sendable {
    let reason: MetalASSFailureReason
    let detail: String

    var errorDescription: String? { "\(reason.rawValue): \(detail)" }
}

enum MetalASSSamplerMode: String, Sendable {
    case nearest
    case linear
}

enum MetalASSTextureCoordinateMode: String, Sendable {
    case rectangleEdges
    case texelCenters
}

enum MetalASSFragmentAlphaMode: String, Sendable {
    case straight
    case premultiplied
}

enum MetalASSDrawableEncoding: String, Sendable {
    case linear
    case sRGB

    var pixelFormat: MTLPixelFormat {
        switch self {
        case .linear: .bgra8Unorm
        case .sRGB: .bgra8Unorm_srgb
        }
    }
}

struct MetalASSRenderConfiguration: Equatable, Sendable {
    var sampler: MetalASSSamplerMode = .linear
    var textureCoordinates: MetalASSTextureCoordinateMode = .rectangleEdges
    var fragmentAlpha: MetalASSFragmentAlphaMode = .straight
    var drawableEncoding: MetalASSDrawableEncoding = .linear
    /// Diagnostic offset in physical output pixels, not libass coordinates.
    var quadOffsetPixels: Float = 0

    static let production = Self()
}

struct ASSAtlasQuad: Equatable, Sendable {
    let source: CGRect
    let destination: CGRect
    let color: UInt32
}

struct ASSCompositionMetrics: Equatable, Sendable {
    let imageCount: Int
    let copiedBytes: Int
    let uploadBytes: Int
    let drawCalls: Int
    let atlasWidth: Int
    let atlasHeight: Int
    let atlasReallocated: Bool
    /// Bytes initialized on growth or explicitly cleared on buffer reuse.
    /// Includes a previous larger frame's dirty prefix on its first reuse.
    let atlasClearBytes: Int

    init(
        imageCount: Int,
        copiedBytes: Int,
        uploadBytes: Int,
        drawCalls: Int,
        atlasWidth: Int = 0,
        atlasHeight: Int = 0,
        atlasReallocated: Bool = false,
        atlasClearBytes: Int = 0
    ) {
        self.imageCount = imageCount
        self.copiedBytes = copiedBytes
        self.uploadBytes = uploadBytes
        self.drawCalls = drawCalls
        self.atlasWidth = atlasWidth
        self.atlasHeight = atlasHeight
        self.atlasReallocated = atlasReallocated
        self.atlasClearBytes = atlasClearBytes
    }
}

struct ASSPreparedSubtitleFrame: Sendable {
    let strategy: SubtitleCompositionStrategy
    let canvasSize: CGSize
    let textureSize: CGSize
    let bytesPerRow: Int
    let pixels: Data
    let quads: [ASSAtlasQuad]
    let metrics: ASSCompositionMetrics
    var usesBitmapAtlas: Bool = false
}

/// CPU preparation shared by the Metal overlay and the correctness harness.
/// The buffers grow as needed and are reused within one subtitle source. A
/// prepared frame holds a value-semantic Data snapshot, while the private
/// reusable storage is serialized by `state`.
final class ASSSubtitleFramePacker: Sendable {
    private struct Placement {
        let x: Int
        let y: Int
        let width: Int
        let height: Int
    }

    private struct ValidatedRegion {
        let value: ASSRenderedRegion
        let width: Int
        let height: Int
        let stride: Int
        let sourceByteCount: Int
    }

    private struct State: Sendable {
        var atlasStorage = [Data(), Data()]
        var bgraStorage = [Data(), Data()]
        // Bytes outside each slot's last active prefix remain zero. Keep this
        // per slot because the two grow-only buffers can hold different frames.
        var atlasActiveBytes = [0, 0]
        var bgraActiveBytes = [0, 0]
        var nextAtlasStorageIndex = 0
        var nextBGRAStorageIndex = 0
    }

    private let maximumTextureDimension: Int
    private let atlasPadding: Int
    private let maximumBackingBytes: Int
    private let maximumRegionCount: Int
    private let memoryLease: SubtitleMemoryBudget.Lease?
    private let state = Mutex(State())

    init(
        maximumTextureDimension: Int = 8_192,
        atlasPadding: Int = 1,
        maximumBackingBytes: Int = 128 * 1_024 * 1_024,
        maximumRegionCount: Int = 256,
        memoryBudget: SubtitleMemoryBudget? = nil,
        memoryOwner: SubtitleMemoryOwner = .mainStaging
    ) {
        self.maximumTextureDimension = max(1, maximumTextureDimension)
        self.atlasPadding = min(
            max(1, atlasPadding),
            max(1, self.maximumTextureDimension / 4)
        )
        self.maximumBackingBytes = max(1, maximumBackingBytes)
        self.maximumRegionCount = max(1, maximumRegionCount)
        memoryLease = memoryBudget?.acquire(owner: memoryOwner, bytes: 0)
    }

    func prepare(
        regions: [ASSRenderedRegion],
        canvasSize: CGSize,
        strategy: SubtitleCompositionStrategy
    ) -> ASSPreparedSubtitleFrame? {
        state.withLock { state in
            if regions.contains(where: \.isPremultipliedBGRA) {
                guard regions.allSatisfy(\.isPremultipliedBGRA) else { return nil }
                return prepareAtlas(regions: regions, canvasSize: canvasSize, state: &state, bytesPerPixel: 4)
            }
            switch strategy {
            case .metalR8Atlas:
                return prepareAtlas(
                    regions: regions,
                    canvasSize: canvasSize,
                    state: &state
                )
            case .metalBGRA:
                return prepareBGRA(
                    regions: regions,
                    canvasSize: canvasSize,
                    state: &state
                )
            }
        }
    }

    /// Releases grow-only staging storage when a subtitle source is retired.
    /// Source-local frame-to-frame reuse remains unchanged.
    func retireSource() {
        state.withLock {
            $0.atlasStorage = [Data(), Data()]
            $0.bgraStorage = [Data(), Data()]
            $0.atlasActiveBytes = [0, 0]
            $0.bgraActiveBytes = [0, 0]
            $0.nextAtlasStorageIndex = 0
            $0.nextBGRAStorageIndex = 0
            _ = memoryLease?.resize(to: 0)
        }
    }

    var retainedStorageByteCountForTesting: Int {
        state.withLock {
            $0.atlasStorage.reduce(0) { $0 + $1.count }
                + $0.bgraStorage.reduce(0) { $0 + $1.count }
        }
    }

    private func prepareAtlas(
        regions: [ASSRenderedRegion],
        canvasSize: CGSize,
        state: inout State,
        bytesPerPixel: Int = 1
    ) -> ASSPreparedSubtitleFrame? {
        guard validCanvas(canvasSize),
              let nonempty = validate(regions)
        else { return nil }
        guard !nonempty.isEmpty else {
            return emptyFrame(strategy: .metalR8Atlas, canvasSize: canvasSize)
        }

        guard let packed = pack(nonempty) else { return nil }
        let (byteCount, byteCountOverflow) = (packed.width * bytesPerPixel).multipliedReportingOverflow(
            by: packed.height
        )
        guard !byteCountOverflow, byteCount <= maximumBackingBytes else { return nil }
        let storageIndex = state.nextAtlasStorageIndex
        state.nextAtlasStorageIndex =
            (state.nextAtlasStorageIndex + 1) % state.atlasStorage.count
        let previousMaximumStorage = state.atlasStorage.map(\.count).max() ?? 0
        let requestedStorage = max(byteCount, previousMaximumStorage)
        let projectedStorageBytes = state.atlasStorage.enumerated().reduce(0) {
            $0 + ($1.offset == storageIndex ? requestedStorage : $1.element.count)
        } + state.bgraStorage.reduce(0) { $0 + $1.count }
        guard memoryLease?.resize(to: projectedStorageBytes) ?? true else {
            return nil
        }
        let clearedBytes = resizeAndClear(
            &state.atlasStorage[storageIndex],
            storageByteCount: requestedStorage,
            clearByteCount: max(byteCount, state.atlasActiveBytes[storageIndex])
        )
        state.atlasActiveBytes[storageIndex] = byteCount
        let atlasReallocated = byteCount > previousMaximumStorage

        var copiedBytes = 0
        state.atlasStorage[storageIndex].withUnsafeMutableBytes { destinationBytes in
            guard let destination = destinationBytes.bindMemory(to: UInt8.self).baseAddress else {
                return
            }
            for (region, placement) in zip(nonempty, packed.placements) {
                let width = placement.width
                let height = placement.height
                copiedBytes += width * height * bytesPerPixel
                region.value.bitmap.withUnsafeBytes { sourceBytes in
                    guard let source = sourceBytes.bindMemory(to: UInt8.self).baseAddress else {
                        return
                    }
                    for row in 0..<height {
                        let sourceStart = source.advanced(by: row * region.stride)
                        let destinationStart = destination.advanced(
                            by: ((placement.y + row) * packed.width + placement.x) * bytesPerPixel
                        )
                        destinationStart.update(from: sourceStart, count: width * bytesPerPixel)
                    }
                }
                replicateAtlasPadding(
                    destination,
                    textureWidth: packed.width,
                    placement: placement,
                    padding: atlasPadding,
                    bytesPerPixel: bytesPerPixel
                )
            }
        }

        let quads = zip(nonempty, packed.placements).map { region, placement in
            ASSAtlasQuad(
                source: CGRect(
                    x: placement.x,
                    y: placement.y,
                    width: placement.width,
                    height: placement.height
                ),
                destination: region.value.frame,
                color: region.value.color
            )
        }
        return ASSPreparedSubtitleFrame(
            strategy: bytesPerPixel == 4 ? .metalBGRA : .metalR8Atlas,
            canvasSize: canvasSize,
            textureSize: CGSize(width: packed.width, height: packed.height),
            bytesPerRow: packed.width * bytesPerPixel,
            pixels: state.atlasStorage[storageIndex],
            quads: quads,
            metrics: ASSCompositionMetrics(
                imageCount: nonempty.count,
                copiedBytes: copiedBytes,
                uploadBytes: byteCount,
                drawCalls: 1,
                atlasWidth: packed.width,
                atlasHeight: packed.height,
                atlasReallocated: atlasReallocated,
                atlasClearBytes: clearedBytes
            ),
            usesBitmapAtlas: bytesPerPixel == 4
        )
    }

    private func prepareBGRA(
        regions: [ASSRenderedRegion],
        canvasSize: CGSize,
        state: inout State
    ) -> ASSPreparedSubtitleFrame? {
        guard let width = checkedTextureDimension(canvasSize.width),
              let height = checkedTextureDimension(canvasSize.height),
              let validated = validate(regions)
        else { return nil }

        let (pixelCount, pixelOverflow) = width.multipliedReportingOverflow(by: height)
        let (byteCount, byteOverflow) = pixelCount.multipliedReportingOverflow(by: 4)
        guard !pixelOverflow,
              !byteOverflow,
              byteCount <= maximumBackingBytes
        else { return nil }
        let storageIndex = state.nextBGRAStorageIndex
        state.nextBGRAStorageIndex =
            (state.nextBGRAStorageIndex + 1) % state.bgraStorage.count
        let previousMaximumStorage = state.bgraStorage.map(\.count).max() ?? 0
        let requestedStorage = max(byteCount, previousMaximumStorage)
        let projectedStorageBytes = state.bgraStorage.enumerated().reduce(0) {
            $0 + ($1.offset == storageIndex ? requestedStorage : $1.element.count)
        } + state.atlasStorage.reduce(0) { $0 + $1.count }
        guard memoryLease?.resize(to: projectedStorageBytes) ?? true else {
            return nil
        }
        let clearedBytes = resizeAndClear(
            &state.bgraStorage[storageIndex],
            storageByteCount: requestedStorage,
            clearByteCount: max(byteCount, state.bgraActiveBytes[storageIndex])
        )
        state.bgraActiveBytes[storageIndex] = byteCount
        let atlasReallocated = byteCount > previousMaximumStorage

        var copiedBytes = 0
        state.bgraStorage[storageIndex].withUnsafeMutableBytes { destinationBytes in
            guard let destination = destinationBytes.bindMemory(to: UInt8.self).baseAddress else {
                return
            }
            for region in validated {
                copiedBytes += region.width * region.height
                composite(
                    region,
                    into: destination,
                    destinationWidth: width,
                    destinationHeight: height
                )
            }
        }

        return ASSPreparedSubtitleFrame(
            strategy: .metalBGRA,
            canvasSize: canvasSize,
            textureSize: CGSize(width: width, height: height),
            bytesPerRow: width * 4,
            pixels: state.bgraStorage[storageIndex],
            quads: [ASSAtlasQuad(
                source: CGRect(x: 0, y: 0, width: width, height: height),
                destination: CGRect(x: 0, y: 0, width: width, height: height),
                color: 0
            )],
            metrics: ASSCompositionMetrics(
                imageCount: validated.count,
                copiedBytes: copiedBytes,
                uploadBytes: byteCount,
                drawCalls: 1,
                atlasWidth: width,
                atlasHeight: height,
                atlasReallocated: atlasReallocated,
                atlasClearBytes: clearedBytes
            )
        )
    }

    private func emptyFrame(
        strategy: SubtitleCompositionStrategy,
        canvasSize: CGSize
    ) -> ASSPreparedSubtitleFrame {
        ASSPreparedSubtitleFrame(
            strategy: strategy,
            canvasSize: canvasSize,
            textureSize: .zero,
            bytesPerRow: 0,
            pixels: Data(),
            quads: [],
            metrics: ASSCompositionMetrics(
                imageCount: 0,
                copiedBytes: 0,
                uploadBytes: 0,
                drawCalls: 1
            )
        )
    }

    private func pack(
        _ regions: [ValidatedRegion]
    ) -> (width: Int, height: Int, placements: [Placement])? {
        let padding = atlasPadding
        let (doublePadding, paddingOverflow) = padding.multipliedReportingOverflow(by: 2)
        guard !paddingOverflow else { return nil }
        var widest = 1
        var totalArea = 0
        for region in regions {
            let (paddedWidth, widthOverflow) = region.width.addingReportingOverflow(
                doublePadding
            )
            let (paddedHeight, heightOverflow) = region.height.addingReportingOverflow(
                doublePadding
            )
            let (area, areaOverflow) = paddedWidth.multipliedReportingOverflow(
                by: paddedHeight
            )
            let (nextArea, totalOverflow) = totalArea.addingReportingOverflow(area)
            guard !widthOverflow,
                  !heightOverflow,
                  !areaOverflow,
                  !totalOverflow,
                  paddedWidth <= maximumTextureDimension,
                  paddedHeight <= maximumTextureDimension,
                  nextArea <= maximumBackingBytes
            else { return nil }
            widest = max(widest, paddedWidth)
            totalArea = nextArea
        }
        guard let initialWidth = nextPowerOfTwo(
            max(widest, Int(Double(totalArea).squareRoot()))
        ) else { return nil }
        var textureWidth = initialWidth
        textureWidth = max(32, textureWidth)

        let packingOrder = regions.indices.sorted { lhs, rhs in
            let leftHeight = regions[lhs].height
            let rightHeight = regions[rhs].height
            if leftHeight != rightHeight { return leftHeight > rightHeight }
            let leftWidth = regions[lhs].width
            let rightWidth = regions[rhs].width
            if leftWidth != rightWidth { return leftWidth > rightWidth }
            return lhs < rhs
        }

        while textureWidth <= maximumTextureDimension {
            var cursorX = padding
            var cursorY = padding
            var rowHeight = 0
            var placements = Array<Placement?>(repeating: nil, count: regions.count)

            for index in packingOrder {
                let region = regions[index]
                let width = region.width
                let height = region.height
                let (rightEdge, rightEdgeOverflow) = cursorX.addingReportingOverflow(
                    width + padding
                )
                guard !rightEdgeOverflow else { return nil }
                if rightEdge > textureWidth {
                    cursorX = padding
                    let (nextRow, rowOverflow) = cursorY.addingReportingOverflow(
                        rowHeight + doublePadding
                    )
                    guard !rowOverflow else { return nil }
                    cursorY = nextRow
                    rowHeight = 0
                }
                placements[index] = Placement(
                    x: cursorX,
                    y: cursorY,
                    width: width,
                    height: height
                )
                let (nextCursorX, cursorOverflow) = cursorX.addingReportingOverflow(
                    width + doublePadding
                )
                guard !cursorOverflow else { return nil }
                cursorX = nextCursorX
                rowHeight = max(rowHeight, height)
            }

            let (rowBottom, rowBottomOverflow) = cursorY.addingReportingOverflow(rowHeight)
            let (usedHeight, usedHeightOverflow) = rowBottom.addingReportingOverflow(padding)
            guard !rowBottomOverflow,
                  !usedHeightOverflow,
                  let roundedHeight = nextPowerOfTwo(usedHeight)
            else { return nil }
            let textureHeight = max(32, roundedHeight)
            if textureHeight <= maximumTextureDimension {
                let (byteCount, byteCountOverflow) = textureWidth.multipliedReportingOverflow(
                    by: textureHeight
                )
                guard !byteCountOverflow, byteCount <= maximumBackingBytes else {
                    return nil
                }
                return (
                    textureWidth,
                    textureHeight,
                    placements.compactMap { $0 }
                )
            }
            let (nextWidth, widthOverflow) = textureWidth.multipliedReportingOverflow(by: 2)
            guard !widthOverflow, nextWidth > textureWidth else { return nil }
            textureWidth = nextWidth
        }
        return nil
    }

    private func replicateAtlasPadding(
        _ bytes: UnsafeMutablePointer<UInt8>,
        textureWidth: Int,
        placement: Placement,
        padding: Int,
        bytesPerPixel: Int = 1
    ) {
        let x = placement.x
        let y = placement.y
        let width = placement.width
        let height = placement.height
        for row in 0..<height {
            let offset = ((y + row) * textureWidth + x) * bytesPerPixel
            for inset in 1...padding {
                for channel in 0..<bytesPerPixel {
                    bytes[offset - inset * bytesPerPixel + channel] = bytes[offset + channel]
                    bytes[offset + (width - 1 + inset) * bytesPerPixel + channel] = bytes[offset + (width - 1) * bytesPerPixel + channel]
                }
            }
        }
        let paddedWidth = (width + 2 * padding) * bytesPerPixel
        let first = (y * textureWidth + x - padding) * bytesPerPixel
        let last = ((y + height - 1) * textureWidth + x - padding) * bytesPerPixel
        for inset in 1...padding {
            let top = ((y - inset) * textureWidth + x - padding) * bytesPerPixel
            bytes.advanced(by: top).update(
                from: bytes.advanced(by: first),
                count: paddedWidth
            )
            let bottom = ((y + height - 1 + inset) * textureWidth + x - padding) * bytesPerPixel
            bytes.advanced(by: bottom).update(
                from: bytes.advanced(by: last),
                count: paddedWidth
            )
        }
    }

    private func composite(
        _ region: ValidatedRegion,
        into destination: UnsafeMutablePointer<UInt8>,
        destinationWidth: Int,
        destinationHeight: Int
    ) {
        let sourceWidth = region.width
        let sourceHeight = region.height
        let destinationX = Int(region.value.frame.minX)
        let destinationY = Int(region.value.frame.minY)
        let red = Int((region.value.color >> 24) & 0xff)
        let green = Int((region.value.color >> 16) & 0xff)
        let blue = Int((region.value.color >> 8) & 0xff)
        let alpha = 255 - Int(region.value.color & 0xff)

        region.value.bitmap.withUnsafeBytes { sourceBytes in
            guard let source = sourceBytes.bindMemory(to: UInt8.self).baseAddress else { return }
            for sourceY in 0..<sourceHeight {
                let targetY = destinationY + sourceY
                guard targetY >= 0, targetY < destinationHeight else { continue }
                for sourceX in 0..<sourceWidth {
                    let targetX = destinationX + sourceX
                    guard targetX >= 0, targetX < destinationWidth else { continue }
                    let coverage = Int(source[sourceY * region.stride + sourceX])
                    let sourceAlpha = alpha * coverage
                    let destinationOffset = (targetY * destinationWidth + targetX) * 4
                    let inverseAlpha = 255 * 255 - sourceAlpha
                    let oldBlue = Int(destination[destinationOffset])
                    let oldGreen = Int(destination[destinationOffset + 1])
                    let oldRed = Int(destination[destinationOffset + 2])
                    let oldAlpha = Int(destination[destinationOffset + 3])
                    destination[destinationOffset] = UInt8(
                        (blue * sourceAlpha + oldBlue * inverseAlpha) / (255 * 255)
                    )
                    destination[destinationOffset + 1] = UInt8(
                        (green * sourceAlpha + oldGreen * inverseAlpha) / (255 * 255)
                    )
                    destination[destinationOffset + 2] = UInt8(
                        (red * sourceAlpha + oldRed * inverseAlpha) / (255 * 255)
                    )
                    destination[destinationOffset + 3] = UInt8(
                        (sourceAlpha * 255 + oldAlpha * inverseAlpha) / (255 * 255)
                    )
                }
            }
        }
    }

    private func resizeAndClear(
        _ data: inout Data,
        storageByteCount: Int,
        clearByteCount: Int
    ) -> Int {
        if data.count < storageByteCount {
            data = Data(count: storageByteCount)
            return storageByteCount
        } else {
            // Preserve the zero tail of the full Data snapshot without
            // clearing its historical high-water capacity on every frame.
            data.resetBytes(in: 0..<clearByteCount)
            return clearByteCount
        }
    }

    private func validate(
        _ regions: [ASSRenderedRegion]
    ) -> [ValidatedRegion]? {
        guard regions.count <= maximumRegionCount else { return nil }
        var validated: [ValidatedRegion] = []
        validated.reserveCapacity(regions.count)
        var retainedSourceBytes = 0
        for region in regions {
            let frame = region.frame
            guard frame.minX.isFinite,
                  frame.minY.isFinite,
                  frame.maxX.isFinite,
                  frame.maxY.isFinite,
                  frame.minX >= CGFloat(Int32.min),
                  frame.minY >= CGFloat(Int32.min),
                  frame.maxX <= CGFloat(Int32.max),
                  frame.maxY <= CGFloat(Int32.max),
                  frame.width.isFinite,
                  frame.height.isFinite
            else { return nil }
            if frame.width <= 0 || frame.height <= 0 || region.bitmap.isEmpty {
                continue
            }
            let bitmapSize = region.bitmapSize ?? frame.size
            guard let width = checkedRegionDimension(bitmapSize.width),
                  let height = checkedRegionDimension(bitmapSize.height),
                  region.stride >= width * (region.isPremultipliedBGRA ? 4 : 1)
            else { return nil }
            let (sourceByteCount, sourceOverflow) = region.stride
                .multipliedReportingOverflow(by: height)
            let (nextRetainedBytes, totalOverflow) = retainedSourceBytes
                .addingReportingOverflow(region.bitmap.count)
            guard !sourceOverflow,
                  !totalOverflow,
                  sourceByteCount <= region.bitmap.count,
                  sourceByteCount <= maximumBackingBytes,
                  nextRetainedBytes <= maximumBackingBytes
            else { return nil }
            retainedSourceBytes = nextRetainedBytes
            validated.append(ValidatedRegion(
                value: region,
                width: width,
                height: height,
                stride: region.stride,
                sourceByteCount: sourceByteCount
            ))
        }
        return validated
    }

    private func validCanvas(_ size: CGSize) -> Bool {
        checkedTextureDimension(size.width) != nil
            && checkedTextureDimension(size.height) != nil
    }

    private func checkedTextureDimension(_ value: CGFloat) -> Int? {
        guard value.isFinite,
              value > 0,
              value <= CGFloat(maximumTextureDimension)
        else { return nil }
        let rounded = value.rounded(.up)
        guard rounded <= CGFloat(maximumTextureDimension) else { return nil }
        return Int(rounded)
    }

    private func checkedRegionDimension(_ value: CGFloat) -> Int? {
        guard value.isFinite,
              value > 0,
              value <= CGFloat(maximumTextureDimension),
              value.rounded(.towardZero) == value
        else { return nil }
        return Int(value)
    }

    private func nextPowerOfTwo(_ value: Int) -> Int? {
        guard value > 1 else { return 1 }
        let shift = Int.bitWidth - (value - 1).leadingZeroBitCount
        guard shift < Int.bitWidth - 1 else { return nil }
        return 1 << shift
    }
}

@MainActor
final class MetalASSSubtitleRenderer {
    private struct Vertex {
        var position: SIMD2<Float>
        var textureCoordinate: SIMD2<Float>
        var color: SIMD4<UInt8>
    }

    private final class FrameResources: @unchecked Sendable {
        var texture: (any MTLTexture)?
        var vertexBuffer: (any MTLBuffer)?
        var vertexCapacity = 0
    }

    private final class ResourcePool: @unchecked Sendable {
        private let lock = NSLock()
        private var available: [FrameResources] = []

        func acquire() -> FrameResources {
            lock.withLock { available.popLast() ?? FrameResources() }
        }

        func release(_ resources: FrameResources) {
            lock.withLock { available.append(resources) }
        }
    }

    private let device: any MTLDevice
    private let commandQueue: any MTLCommandQueue
    private let r8Pipeline: any MTLRenderPipelineState
    private let bgraPipeline: any MTLRenderPipelineState
    private let sampler: any MTLSamplerState
    private let configuration: MetalASSRenderConfiguration
    private let resourcePool = ResourcePool()
    private(set) var failureEvents = 0
    private(set) var submittedFrames = 0
    private(set) var submittedUploadBytes = 0
    private(set) var drawableAcquisitionCount = 0
    private(set) var drawableAcquisitionFailures = 0
    private(set) var commandBufferFailures = 0
    private(set) var textureAllocationFailures = 0
    private(set) var bufferAllocationFailures = 0
    private(set) var commandBuffersSubmitted = 0
    private(set) var lastOffscreenGPUDurationSeconds: Double?
    private var synchronousFailure: MetalASSFailureReason?
    /// Metal-capable macOS GPU families support 16,384-wide 2D textures.
    ///
    /// Metal exposes this limit through the macOS GPU-family capability table,
    /// not as an `MTLDevice` property in every supported SDK.
    var maximumTextureDimension2D: Int { 16_384 }

    init(
        layer: CAMetalLayer,
        configuration: MetalASSRenderConfiguration = .production
    ) throws {
        guard let device = MTLCreateSystemDefaultDevice() else {
            throw MetalASSRendererError(
                reason: .deviceInitialization,
                detail: "MTLCreateSystemDefaultDevice returned nil"
            )
        }
        guard let commandQueue = device.makeCommandQueue() else {
            throw MetalASSRendererError(
                reason: .deviceInitialization,
                detail: "Metal command queue creation returned nil"
            )
        }
        self.device = device
        self.commandQueue = commandQueue
        self.configuration = configuration
        layer.device = device
        layer.pixelFormat = configuration.drawableEncoding.pixelFormat
        layer.framebufferOnly = true
        layer.isOpaque = false
        layer.backgroundColor = nil
        layer.colorspace = CGColorSpace(name: CGColorSpace.sRGB)
        layer.presentsWithTransaction = false
        layer.displaySyncEnabled = true

        let library: any MTLLibrary
        do {
            library = try NativeMetalShaderLibrary.load(device: device)
        } catch {
            throw MetalASSRendererError(
                reason: .pipelineCreation,
                detail: "shader library creation failed: \(error.localizedDescription)"
            )
        }
        guard let vertex = library.makeFunction(name: "ass_vertex"),
              let r8StraightFragment = library.makeFunction(name: "ass_r8_fragment"),
              let r8PremultipliedFragment = library.makeFunction(
                name: "ass_r8_premultiplied_fragment"
              ),
              let bgraFragment = library.makeFunction(name: "ass_bgra_fragment")
        else {
            throw MetalASSRendererError(
                reason: .pipelineCreation,
                detail: "required Metal ASS shader function is unavailable"
            )
        }
        let r8Fragment = configuration.fragmentAlpha == .straight
            ? r8StraightFragment
            : r8PremultipliedFragment

        let vertexDescriptor = MTLVertexDescriptor()
        vertexDescriptor.attributes[0].format = .float2
        vertexDescriptor.attributes[0].offset = 0
        vertexDescriptor.attributes[0].bufferIndex = 0
        vertexDescriptor.attributes[1].format = .float2
        vertexDescriptor.attributes[1].offset = 8
        vertexDescriptor.attributes[1].bufferIndex = 0
        vertexDescriptor.attributes[2].format = .uchar4Normalized
        vertexDescriptor.attributes[2].offset = 16
        vertexDescriptor.attributes[2].bufferIndex = 0
        vertexDescriptor.layouts[0].stride = MemoryLayout<Vertex>.stride

        do {
            r8Pipeline = try Self.makePipeline(
                device: device,
                vertex: vertex,
                fragment: r8Fragment,
                vertexDescriptor: vertexDescriptor,
                premultiplied: configuration.fragmentAlpha == .premultiplied,
                pixelFormat: configuration.drawableEncoding.pixelFormat
            )
            bgraPipeline = try Self.makePipeline(
                device: device,
                vertex: vertex,
                fragment: bgraFragment,
                vertexDescriptor: vertexDescriptor,
                premultiplied: true,
                pixelFormat: configuration.drawableEncoding.pixelFormat
            )
        } catch {
            throw MetalASSRendererError(
                reason: .pipelineCreation,
                detail: "render pipeline creation failed: \(error.localizedDescription)"
            )
        }
        let samplerDescriptor = MTLSamplerDescriptor()
        let filter: MTLSamplerMinMagFilter = configuration.sampler == .linear
            ? .linear
            : .nearest
        samplerDescriptor.minFilter = filter
        samplerDescriptor.magFilter = filter
        samplerDescriptor.sAddressMode = .clampToEdge
        samplerDescriptor.tAddressMode = .clampToEdge
        guard let sampler = device.makeSamplerState(descriptor: samplerDescriptor) else {
            throw MetalASSRendererError(
                reason: .pipelineCreation,
                detail: "sampler creation returned nil"
            )
        }
        self.sampler = sampler
    }

    func draw(
        _ frame: ASSPreparedSubtitleFrame,
        in layer: CAMetalLayer,
        asynchronousFailure: (@MainActor @Sendable (MetalASSFailureReason) -> Void)? = nil
    ) -> Result<Void, MetalASSFailureReason> {
        guard layer.drawableSize.width.isFinite,
              layer.drawableSize.height.isFinite,
              layer.drawableSize.width > 0,
              layer.drawableSize.height > 0
        else {
            failureEvents += 1
            return .failure(.invalidBackingGeometry)
        }
        drawableAcquisitionCount += 1
        guard let drawable = layer.nextDrawable() else {
            failureEvents += 1
            drawableAcquisitionFailures += 1
            return .failure(.drawableAcquisition)
        }
        let resources = resourcePool.acquire()
        synchronousFailure = nil
        guard encode(
            frame,
            target: drawable.texture,
            present: drawable,
            resources: resources,
            completion: { [resourcePool] in resourcePool.release(resources) },
            asynchronousFailure: asynchronousFailure
        ) else {
            resourcePool.release(resources)
            failureEvents += 1
            return .failure(synchronousFailure ?? .commandBufferCreation)
        }
        submittedFrames += 1
        submittedUploadBytes += frame.metrics.uploadBytes
        return .success(())
    }

    func drawLegacy(_ frame: ASSPreparedSubtitleFrame, in layer: CAMetalLayer) -> Bool {
        if case .success = draw(frame, in: layer) { return true }
        return false
    }

    func renderOffscreen(
        _ frame: ASSPreparedSubtitleFrame,
        targetSize: CGSize? = nil
    ) -> Data? {
        let targetSize = targetSize ?? frame.canvasSize
        let width = max(1, Int(targetSize.width.rounded(.up)))
        let height = max(1, Int(targetSize.height.rounded(.up)))
        let descriptor = MTLTextureDescriptor.texture2DDescriptor(
            pixelFormat: configuration.drawableEncoding.pixelFormat,
            width: width,
            height: height,
            mipmapped: false
        )
        descriptor.usage = [.renderTarget]
        descriptor.storageMode = .shared
        guard let target = device.makeTexture(descriptor: descriptor) else { return nil }
        let resources = resourcePool.acquire()
        guard encode(
            frame,
            target: target,
            resources: resources,
            waitUntilCompleted: true
        ) else {
            resourcePool.release(resources)
            return nil
        }
        resourcePool.release(resources)
        var bytes = Data(count: width * height * 4)
        bytes.withUnsafeMutableBytes { buffer in
            guard let base = buffer.baseAddress else { return }
            target.getBytes(
                base,
                bytesPerRow: width * 4,
                from: MTLRegionMake2D(0, 0, width, height),
                mipmapLevel: 0
            )
        }
        return bytes
    }

    private func encode(
        _ frame: ASSPreparedSubtitleFrame,
        target: any MTLTexture,
        present drawable: (any CAMetalDrawable)? = nil,
        resources: FrameResources,
        completion: (@Sendable () -> Void)? = nil,
        asynchronousFailure: (@MainActor @Sendable (MetalASSFailureReason) -> Void)? = nil,
        waitUntilCompleted: Bool = false
    ) -> Bool {
        guard let commandBuffer = commandQueue.makeCommandBuffer() else {
            synchronousFailure = .commandBufferCreation
            commandBufferFailures += 1
            return false
        }
        let pass = MTLRenderPassDescriptor()
        pass.colorAttachments[0].texture = target
        pass.colorAttachments[0].loadAction = .clear
        pass.colorAttachments[0].storeAction = .store
        pass.colorAttachments[0].clearColor = MTLClearColorMake(0, 0, 0, 0)

        if !frame.quads.isEmpty {
            guard upload(frame, resources: resources),
                  let texture = resources.texture
            else { return false }
            guard let encoder = commandBuffer.makeRenderCommandEncoder(descriptor: pass) else {
                synchronousFailure = .commandEncoderCreation
                commandBufferFailures += 1
                return false
            }
            let vertices = makeVertices(
                frame,
                texture: texture,
                targetSize: CGSize(width: target.width, height: target.height)
            )
            guard uploadVertices(vertices, resources: resources),
                  let vertexBuffer = resources.vertexBuffer
            else { return false }
            var viewport = SIMD2<Float>(
                Float(max(frame.canvasSize.width, 1)),
                Float(max(frame.canvasSize.height, 1))
            )
            encoder.setRenderPipelineState(
                frame.strategy == .metalR8Atlas ? r8Pipeline : bgraPipeline
            )
            encoder.setVertexBuffer(vertexBuffer, offset: 0, index: 0)
            encoder.setVertexBytes(&viewport, length: MemoryLayout.size(ofValue: viewport), index: 1)
            encoder.setFragmentTexture(texture, index: 0)
            encoder.setFragmentSamplerState(sampler, index: 0)
            encoder.drawPrimitives(type: .triangle, vertexStart: 0, vertexCount: vertices.count)
            encoder.endEncoding()
        } else {
            guard let encoder = commandBuffer.makeRenderCommandEncoder(descriptor: pass) else {
                synchronousFailure = .commandEncoderCreation
                commandBufferFailures += 1
                return false
            }
            encoder.endEncoding()
        }

        if let drawable { commandBuffer.present(drawable) }
        if let completion {
            commandBuffer.addCompletedHandler { _ in completion() }
        }
        if let asynchronousFailure {
            commandBuffer.addCompletedHandler { commandBuffer in
                guard commandBuffer.status == .error else { return }
                Task { @MainActor in
                    asynchronousFailure(.commandBufferExecution)
                }
            }
        }
        commandBuffer.commit()
        commandBuffersSubmitted += 1
        if waitUntilCompleted {
            commandBuffer.waitUntilCompleted()
            let duration = commandBuffer.gpuEndTime - commandBuffer.gpuStartTime
            lastOffscreenGPUDurationSeconds = duration.isFinite && duration >= 0
                ? duration
                : nil
            return commandBuffer.status != .error
        }
        // Completion owns resource release after commit. Asynchronous GPU
        // errors are not a synchronous encode failure and must not cause the
        // same resource set to be returned to the pool twice.
        return true
    }

    private func upload(
        _ frame: ASSPreparedSubtitleFrame,
        resources: FrameResources
    ) -> Bool {
        let width = Int(frame.textureSize.width)
        let height = Int(frame.textureSize.height)
        guard width > 0, height > 0 else { return true }
        let pixelFormat: MTLPixelFormat = frame.strategy == .metalR8Atlas
            ? .r8Unorm
            : .bgra8Unorm
        if resources.texture == nil
            || resources.texture!.pixelFormat != pixelFormat
            || resources.texture!.width < width
            || resources.texture!.height < height
        {
            let descriptor = MTLTextureDescriptor.texture2DDescriptor(
                pixelFormat: pixelFormat,
                width: width,
                height: height,
                mipmapped: false
            )
            descriptor.usage = [.shaderRead]
            descriptor.storageMode = .shared
            resources.texture = device.makeTexture(descriptor: descriptor)
        }
        guard let texture = resources.texture else {
            synchronousFailure = .textureAllocation
            textureAllocationFailures += 1
            return false
        }
        frame.pixels.withUnsafeBytes { bytes in
            guard let base = bytes.baseAddress else { return }
            texture.replace(
                region: MTLRegionMake2D(0, 0, width, height),
                mipmapLevel: 0,
                withBytes: base,
                bytesPerRow: frame.bytesPerRow
            )
        }
        return true
    }

    private func makeVertices(
        _ frame: ASSPreparedSubtitleFrame,
        texture: any MTLTexture,
        targetSize: CGSize
    ) -> [Vertex] {
        var vertices: [Vertex] = []
        vertices.reserveCapacity(frame.quads.count * 6)
        for quad in frame.quads {
            let color = SIMD4<UInt8>(
                UInt8((quad.color >> 24) & 0xff),
                UInt8((quad.color >> 16) & 0xff),
                UInt8((quad.color >> 8) & 0xff),
                255 - UInt8(quad.color & 0xff)
            )
            let xOffset = configuration.quadOffsetPixels
                * Float(frame.canvasSize.width / max(targetSize.width, 1))
            let yOffset = configuration.quadOffsetPixels
                * Float(frame.canvasSize.height / max(targetSize.height, 1))
            let x0 = Float(quad.destination.minX) + xOffset
            let y0 = Float(quad.destination.minY) + yOffset
            let x1 = Float(quad.destination.maxX) + xOffset
            let y1 = Float(quad.destination.maxY) + yOffset
            let texelInset: Float = configuration.textureCoordinates == .texelCenters
                ? 0.5
                : 0
            let u0 = (Float(quad.source.minX) + texelInset) / Float(texture.width)
            let v0 = (Float(quad.source.minY) + texelInset) / Float(texture.height)
            let u1 = (Float(quad.source.maxX) - texelInset) / Float(texture.width)
            let v1 = (Float(quad.source.maxY) - texelInset) / Float(texture.height)
            let topLeft = Vertex(
                position: SIMD2(x0, y0), textureCoordinate: SIMD2(u0, v0), color: color
            )
            let bottomLeft = Vertex(
                position: SIMD2(x0, y1), textureCoordinate: SIMD2(u0, v1), color: color
            )
            let topRight = Vertex(
                position: SIMD2(x1, y0), textureCoordinate: SIMD2(u1, v0), color: color
            )
            let bottomRight = Vertex(
                position: SIMD2(x1, y1), textureCoordinate: SIMD2(u1, v1), color: color
            )
            vertices += [topLeft, bottomLeft, topRight, topRight, bottomLeft, bottomRight]
        }
        return vertices
    }

    private func uploadVertices(
        _ vertices: [Vertex],
        resources: FrameResources
    ) -> Bool {
        let required = vertices.count * MemoryLayout<Vertex>.stride
        if resources.vertexBuffer == nil || resources.vertexCapacity < required {
            resources.vertexCapacity = max(
                required,
                max(resources.vertexCapacity * 2, 4_096)
            )
            resources.vertexBuffer = device.makeBuffer(
                length: resources.vertexCapacity,
                options: .storageModeShared
            )
        }
        guard let vertexBuffer = resources.vertexBuffer else {
            synchronousFailure = .bufferAllocation
            bufferAllocationFailures += 1
            return false
        }
        vertices.withUnsafeBytes { bytes in
            guard let base = bytes.baseAddress else { return }
            vertexBuffer.contents().copyMemory(from: base, byteCount: required)
        }
        return true
    }

    private static func makePipeline(
        device: any MTLDevice,
        vertex: any MTLFunction,
        fragment: any MTLFunction,
        vertexDescriptor: MTLVertexDescriptor,
        premultiplied: Bool,
        pixelFormat: MTLPixelFormat
    ) throws -> any MTLRenderPipelineState {
        let descriptor = MTLRenderPipelineDescriptor()
        descriptor.vertexFunction = vertex
        descriptor.fragmentFunction = fragment
        descriptor.vertexDescriptor = vertexDescriptor
        descriptor.colorAttachments[0].pixelFormat = pixelFormat
        descriptor.colorAttachments[0].isBlendingEnabled = true
        descriptor.colorAttachments[0].sourceRGBBlendFactor = premultiplied ? .one : .sourceAlpha
        descriptor.colorAttachments[0].destinationRGBBlendFactor = .oneMinusSourceAlpha
        descriptor.colorAttachments[0].sourceAlphaBlendFactor = .one
        descriptor.colorAttachments[0].destinationAlphaBlendFactor = .oneMinusSourceAlpha
        return try device.makeRenderPipelineState(descriptor: descriptor)
    }

}

#include <metal_stdlib>
using namespace metal;

struct ASSVertexIn {
    float2 position [[attribute(0)]];
    float2 textureCoordinate [[attribute(1)]];
    float4 color [[attribute(2)]];
};

struct ASSVertexOut {
    float4 position [[position]];
    float2 textureCoordinate;
    float4 color;
};

vertex ASSVertexOut ass_vertex(
    ASSVertexIn input [[stage_in]],
    constant float2 &viewport [[buffer(1)]])
{
    ASSVertexOut output;
    float2 unit = input.position / viewport;
    output.position = float4(unit.x * 2.0 - 1.0, 1.0 - unit.y * 2.0, 0.0, 1.0);
    output.textureCoordinate = input.textureCoordinate;
    output.color = input.color;
    return output;
}

fragment float4 ass_r8_fragment(
    ASSVertexOut input [[stage_in]],
    texture2d<float> atlas [[texture(0)]],
    sampler atlasSampler [[sampler(0)]])
{
    float coverage = atlas.sample(atlasSampler, input.textureCoordinate).r;
    return float4(input.color.rgb, input.color.a * coverage);
}

fragment float4 ass_r8_premultiplied_fragment(
    ASSVertexOut input [[stage_in]],
    texture2d<float> atlas [[texture(0)]],
    sampler atlasSampler [[sampler(0)]])
{
    float alpha = input.color.a * atlas.sample(
        atlasSampler,
        input.textureCoordinate
    ).r;
    return float4(input.color.rgb * alpha, alpha);
}

fragment float4 ass_bgra_fragment(
    ASSVertexOut input [[stage_in]],
    texture2d<float> surface [[texture(0)]],
    sampler surfaceSampler [[sampler(0)]])
{
    return surface.sample(surfaceSampler, input.textureCoordinate);
}

struct PiPVideoVertexOut {
    float4 position [[position]];
    float2 textureCoordinate;
};

vertex PiPVideoVertexOut pip_video_vertex(
    uint vertexID [[vertex_id]],
    constant float2 *coordinates [[buffer(0)]]) {
    const float2 positions[6] = {
        float2(-1.0,  1.0), float2(-1.0, -1.0), float2( 1.0,  1.0),
        float2( 1.0,  1.0), float2(-1.0, -1.0), float2( 1.0, -1.0)
    };
    PiPVideoVertexOut output;
    output.position = float4(positions[vertexID], 0.0, 1.0);
    output.textureCoordinate = coordinates[vertexID];
    return output;
}

fragment float4 pip_bgra_fragment(
    PiPVideoVertexOut input [[stage_in]],
    texture2d<float> source [[texture(0)]],
    sampler sourceSampler [[sampler(0)]])
{
    return source.sample(sourceSampler, input.textureCoordinate);
}

fragment float4 pip_nv12_fragment(
    PiPVideoVertexOut input [[stage_in]],
    texture2d<float> lumaTexture [[texture(0)]],
    texture2d<float> chromaTexture [[texture(1)]],
    sampler sourceSampler [[sampler(0)]],
    constant uint &sourceEncoding [[buffer(0)]],
    constant float4 &coefficients [[buffer(1)]])
{
    bool fullRange = (sourceEncoding & 1) != 0;
    bool tenBit = (sourceEncoding & 2) != 0;
    // P010 holds each ten-bit code in the high bits of a sixteen-bit sample.
    float codeScale = tenBit ? 65535.0 / 64.0 : 255.0;
    float bitScale = tenBit ? 4.0 : 1.0;
    float maximumCode = tenBit ? 1023.0 : 255.0;
    float y = lumaTexture.sample(sourceSampler, input.textureCoordinate).r * codeScale;
    float2 chroma = chromaTexture.sample(
        sourceSampler,
        input.textureCoordinate
    ).rg * codeScale - float2(128.0 * bitScale);
    y = fullRange ? y / maximumCode : (y - 16.0 * bitScale) / (219.0 * bitScale);
    chroma /= fullRange ? maximumCode : 224.0 * bitScale;
    float r = y + coefficients.x * chroma.y;
    float g = y + coefficients.y * chroma.x + coefficients.z * chroma.y;
    float b = y + coefficients.w * chroma.x;
    return float4(saturate(float3(r, g, b)), 1.0);
}

struct PiPSubtitleVertex {
    float2 position;
    float2 textureCoordinate;
    float4 color;
};

struct PiPSubtitleVertexOut {
    float4 position [[position]];
    float2 textureCoordinate;
    float4 color;
};

vertex PiPSubtitleVertexOut pip_subtitle_vertex(
    device const PiPSubtitleVertex *vertices [[buffer(0)]],
    constant float2 &viewport [[buffer(1)]],
    uint vertexID [[vertex_id]])
{
    PiPSubtitleVertex input = vertices[vertexID];
    float2 unit = input.position / viewport;
    PiPSubtitleVertexOut output;
    output.position = float4(
        unit.x * 2.0 - 1.0,
        1.0 - unit.y * 2.0,
        0.0,
        1.0
    );
    output.textureCoordinate = input.textureCoordinate;
    output.color = input.color;
    return output;
}

fragment float4 pip_subtitle_fragment(
    PiPSubtitleVertexOut input [[stage_in]],
    texture2d<float> atlas [[texture(0)]],
    sampler atlasSampler [[sampler(0)]])
{
    float coverage = atlas.sample(atlasSampler, input.textureCoordinate).r;
    return float4(input.color.rgb, input.color.a * coverage);
}

fragment float4 pip_bitmap_subtitle_fragment(
    PiPSubtitleVertexOut input [[stage_in]],
    texture2d<float> atlas [[texture(0)]],
    sampler atlasSampler [[sampler(0)]])
{
    return atlas.sample(atlasSampler, input.textureCoordinate);
}

// HDR PiP works in display-linear RGB with 1.0 = 203 cd/m2 graphics white.
// BT.2100 PQ is absolute. HLG uses the 1000-nit, gamma-1.2 reference display;
// inverse encoding restores HLG for the system's actual display adaptation.
float3 pip_hdr_weights(uint primaries) {
    return primaries == 9 ? float3(0.2627, 0.6780, 0.0593) : float3(0.2126, 0.7152, 0.0722);
}
float3 pip_hdr_to_linear(float3 encoded, uint transfer, uint primaries) {
    encoded = saturate(encoded);
    if (transfer == 16) {
        float3 p = pow(encoded, float3(1.0 / 78.84375));
        return pow(max(p - 0.8359375, 0.0) / max(18.8515625 - 18.6875 * p, 1e-7),
                   float3(1.0 / 0.1593017578125)) * (10000.0 / 203.0);
    }
    float3 scene = select(encoded * encoded / 3.0,
        (exp((encoded - 0.55991073) / 0.17883277) + 0.28466892) / 12.0, encoded > 0.5);
    return scene * pow(max(dot(scene, pip_hdr_weights(primaries)), 0.0), 0.2) * (1000.0 / 203.0);
}
float3 pip_hdr_from_linear(float3 linear, uint transfer, uint primaries) {
    linear = max(linear, 0.0);
    if (transfer == 16) {
        float3 p = pow(linear * (203.0 / 10000.0), float3(0.1593017578125));
        return saturate(pow((0.8359375 + 18.8515625 * p) / (1.0 + 18.6875 * p), float3(78.84375)));
    }
    float3 display = linear * (203.0 / 1000.0);
    float luma = dot(display, pip_hdr_weights(primaries));
    float3 scene = display / max(pow(max(luma, 0.0), 1.0 / 6.0), 1e-7);
    return saturate(select(sqrt(3.0 * scene),
        0.17883277 * log(max(12.0 * scene - 0.28466892, 1e-7)) + 0.55991073, scene > 1.0 / 12.0));
}
float3 pip_hdr_graphics(float3 srgb, uint primaries) {
    float3 linear = select(srgb / 12.92, pow((srgb + 0.055) / 1.055, float3(2.4)), srgb > 0.04045);
    if (primaries == 9) {
        return float3(dot(linear, float3(0.6274040, 0.3292820, 0.0433136)),
                      dot(linear, float3(0.0690970, 0.9195400, 0.0113612)),
                      dot(linear, float3(0.0163916, 0.0880132, 0.8955950)));
    }
    return linear;
}
fragment float4 pip_hdr_video_fragment(PiPVideoVertexOut input [[stage_in]],
    texture2d<float> luma [[texture(0)]], texture2d<float> chroma [[texture(1)]],
    sampler sourceSampler [[sampler(0)]], constant uint &encoding [[buffer(0)]],
    constant float4 &coefficients [[buffer(1)]], constant uint &transfer [[buffer(2)]],
    constant uint &primaries [[buffer(3)]]) {
    bool full = (encoding & 1) != 0;
    float y = luma.sample(sourceSampler, input.textureCoordinate).r * (65535.0 / 64.0);
    float2 c = chroma.sample(sourceSampler, input.textureCoordinate).rg * (65535.0 / 64.0) - 512.0;
    y = full ? y / 1023.0 : (y - 64.0) / 876.0;
    c /= full ? 1023.0 : 896.0;
    float3 rgb(y + coefficients.x * c.y, y + coefficients.y * c.x + coefficients.z * c.y,
               y + coefficients.w * c.x);
    return float4(pip_hdr_to_linear(rgb, transfer, primaries), 1.0);
}
fragment float4 pip_hdr_text_fragment(PiPSubtitleVertexOut input [[stage_in]],
    texture2d<float> atlas [[texture(0)]], sampler sourceSampler [[sampler(0)]],
    constant uint &primaries [[buffer(3)]]) {
    return float4(pip_hdr_graphics(input.color.rgb, primaries),
                  input.color.a * atlas.sample(sourceSampler, input.textureCoordinate).r);
}
fragment float4 pip_hdr_bitmap_fragment(PiPSubtitleVertexOut input [[stage_in]],
    texture2d<float> atlas [[texture(0)]], sampler sourceSampler [[sampler(0)]],
    constant uint &primaries [[buffer(3)]]) {
    float4 pixel = atlas.sample(sourceSampler, input.textureCoordinate);
    return float4(pip_hdr_graphics(pixel.rgb / max(pixel.a, 1e-7), primaries) * pixel.a, pixel.a);
}
float3 pip_hdr_yuv(float3 rgb, float4 coefficients) {
    float kr = 1.0 - coefficients.x / 2.0, kb = 1.0 - coefficients.w / 2.0;
    float y = dot(rgb, float3(kr, 1.0 - kr - kb, kb));
    return float3(y, (rgb.b - y) / coefficients.w, (rgb.r - y) / coefficients.x);
}
fragment float pip_hdr_luma_fragment(PiPVideoVertexOut input [[stage_in]],
    texture2d<float> linear [[texture(0)]], constant uint &encoding [[buffer(0)]],
    constant float4 &coefficients [[buffer(1)]], constant uint &transfer [[buffer(2)]],
    constant uint &primaries [[buffer(3)]]) {
